          ? 'bg-gradient-to-l from-[var(--brand-green)] to-emerald-500 text-white shadow-lg shadow-emerald-200'
          : 'bg-white text-gray-600 hover:bg-gray-50 border border-gray-200 hover:border-gray-300'
      }`}
    >
      <Icon className="w-4 h-4" />
      {label}
    </motion.button>
  );
});

