          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          className="w-12 h-12 bg-gradient-to-br from-[var(--brand-green)] to-emerald-500 text-white rounded-full shadow-lg hover:shadow-xl flex items-center justify-center"
