            <span className="text-[var(--brand-green)]">العمل الإنساني</span>
          </h2>
          <p className="text-[var(--muted-foreground)] mt-2 max-w-xl mx-auto" style={{ fontSize: "0.9rem", lineHeight: "1.7" }}>
