ProjectCard.displayName = 'ProjectCard';

// مكوّن الـ Loading للمشاريع
const ProjectsSkeleton = () => (
  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
    {[...Array(4)].map((_, i) => (
      <motion.div
        key={i}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: i * 0.1 }}
        className="bg-white rounded-3xl border border-[var(--border)] overflow-hidden"
      >
        <div className="h-56 bg-gradient-to-r from-gray-200 to-gray-300 animate-pulse" />
        <div className="p-6 space-y-3">
          <div className="h-6 bg-gray-200 rounded w-3/4 animate-pulse" />
          <div className="h-4 bg-gray-200 rounded w-full animate-pulse" />
          <div className="h-4 bg-gray-200 rounded w-5/6 animate-pulse" />
          <div className="flex gap-2">
            <div className="h-6 bg-gray-200 rounded-full w-20 animate-pulse" />
            <div className="h-6 bg-gray-200 rounded-full w-24 animate-pulse" />
          </div>
        </div>
      </motion.div>
    ))}
  </div>
);

export function Programs({ setCurrentPage }: ProgramsProps) {
  const [projectItems, setProjectItems] = useState<any[]>(defaultProjects);
  const [contentSource, setContentSource] = useState<'static' | 'sanity' | 'hybrid'>('static');
  const [showDevBadge, setShowDevBadge] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // استخدام الخطاف الديناميكي للمحتوى
  const { data: dynamicProjects, isLoading: dynamicLoading, source, refresh } = useDynamicContent<any>({
    contentType: 'projects',
    enableRealtime: true,
    refreshInterval: 60000 // تحديث كل دقيقة للبيانات الحية
  });

  // إظهار شارة التطوير
  useEffect(() => {
    if (import.meta.env?.DEV) {
      setShowDevBadge(true);
    }
  }, []);

  // تحميل المشاريع بذكاء
  useEffect(() => {
    let cancelled = false;
    const loadProjects = async () => {
      setIsLoading(true);
      
      try {
        // محاولة البيانات الديناميكية أولاً
        if (dynamicProjects && dynamicProjects.length > 0) {
          const normalized = dynamicProjects.slice(0, 8).map((p: any, idx: number) => {
            const category = p.category || 'عام';
            const styles = categoryStyles[category] || categoryStyles['عام'];
            const Icon = categoryIcons[category] || Heart;
            
            return {
              id: p._id || p.id || idx,
              icon: Icon,
              title: p.title || p.name || "مشروع جديد",
              description: p.description || p.excerpt || "وصف مختصر للمشروع",
              insights: p.insights || [`مستفيد: ${p.beneficiaries || '...'}`, `الموقع: ${p.location || '...'}`],
              achievements: p.achievements || [],
              category: p.category || "عام",
              status: p.status || "قيد التنفيذ",
              beneficiaries: typeof p.beneficiaries === "number" ? `${p.beneficiaries.toLocaleString()}` : p.beneficiaries || "...",
              projects: typeof p.progress === "number" ? `${p.progress}%` : p.status || "...",
              progress: p.progress || Math.floor(Math.random() * 50) + 30,
              location: p.location || "...",
              budget: p.budget || "...",
              color: styles.color,
              bg: styles.bg,
              href: p.slug?.current || `projects-${p._id || idx}`,
              image: p.mainImage ? getSanityImageUrl(p.mainImage) : getRandomImage(category),
              featured: p.featured || false,
            };
          });
          
          if (!cancelled && normalized.length > 0) {
            setProjectItems(normalized);
            setContentSource(source as any);
          }
        } else {
          // الرجوع للمحتوى الثابت
          const fallback = SEED_PROJECTS.slice(0, 8).map((p: any, idx: number) => {
            const category = p.category || 'عام';
            const styles = categoryStyles[category] || categoryStyles['عام'];
            const Icon = categoryIcons[category] || Heart;
            
            return {
              id: p.id || idx,
              icon: Icon,
              title: p.title || "مشروع جديد",
              description: p.description || "وصف مختصر للمشروع",
              insights: [p.category || "عام", p.status || "قيد التنفيذ"],
              achievements: [],
              category: p.category || "عام",
              status: p.status || "قيد التنفيذ",
              beneficiaries: p.beneficiaries || "...",
              projects: typeof p.progress === "number" ? `${p.progress}%` : "...",
              progress: p.progress || 50,
              location: p.location || "...",
              color: styles.color,
              bg: styles.bg,
              href: `projects-${p.id || idx}`,
              image: p.image || getRandomImage(category),
            };
          });
          
          if (!cancelled) {
            setProjectItems(fallback);
            setContentSource('static');
          }
        }
      } catch (error) {
        console.error('Error loading projects:', error);
        if (!cancelled) {
          setProjectItems(defaultProjects);
          setContentSource('static');
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false);
        }
      }
    };

    loadProjects();
    return () => { cancelled = true; };
  }, [dynamicProjects, source]);

  // شارة التطوير
  const DevBadge = showDevBadge ? (
    <div className="fixed top-4 left-4 z-50 bg-gradient-to-r from-purple-600 to-indigo-600 text-white text-xs px-4 py-2 rounded-full shadow-lg backdrop-blur-sm">
      <div className="flex items-center gap-2">
        <div className={`w-2.5 h-2.5 rounded-full animate-pulse ${
          contentSource === 'sanity' ? 'bg-green-400' : 
          contentSource === 'hybrid' ? 'bg-blue-400' : 'bg-yellow-400'
        }`} />
        <span className="font-medium">
          {contentSource === 'sanity' ? '🟢 Connected to Sanity CMS' : 
           contentSource === 'hybrid' ? '🔵 Hybrid Mode' : '🟡 Static Content'}
        </span>
      </div>
    </div>
  ) : null;

  // زر التحديث اليدوي
  const RefreshButton = (
    <motion.button
      onClick={refresh}
      disabled={dynamicLoading}
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      className="flex items-center gap-2 text-[var(--brand-green)] hover:text-[var(--brand-green-light)] transition-colors disabled:opacity-50"
    >
      <RefreshCw className={`w-4 h-4 ${dynamicLoading ? 'animate-spin' : ''}`} />
      <span className="text-sm font-medium">تحديث</span>
    </motion.button>
  );

  return (
    <section className="py-24 bg-gradient-to-b from-[var(--background)] to-[var(--brand-green-pale)]/10" style={{ direction: "rtl" }}>
      {DevBadge}
      <div className="max-w-7xl mx-auto px-4 sm:px-6">
        {/* العنوان الترويجي المحسّن */}
        <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 mb-16">
          <div>
            <motion.span
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5 }}
              className="inline-flex items-center gap-2 mb-4 text-[var(--brand-green)] border border-[var(--brand-green)]/30 bg-[var(--brand-green-pale)] px-5 py-1.5 rounded-full text-sm font-semibold"
            >
              <Target className="w-4 h-4" />
              محاور العمل الإنساني
            </motion.span>
            
            <motion.h2
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: 0.1 }}
              className="text-[var(--foreground)] text-3xl md:text-4xl font-bold mb-3"
            >
              برامجنا وقطاعات{" "}
              <span className="text-[var(--brand-green)] relative">
                التدخل
                <motion.div
                  className="absolute -bottom-1 left-0 w-full h-1 bg-[var(--brand-green)]/20 rounded-full"
                  initial={{ width: 0 }}
                  whileInView={{ width: '100%' }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.8, delay: 0.5 }}
                />
              </span>
            </motion.h2>
            
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: 0.2 }}
              className="text-[var(--muted-foreground)] mt-2 max-w-2xl text-base leading-relaxed"
            >
              أربعة محاور متكاملة تشكّل منظومتنا — الإغاثة، والتمكين، والتعليم، والدعوة؛ يعمل كلٌّ منها بمنهجية المسح والتنفيذ والمتابعة ليصل الأثر كاملاً لمن يستحقه
            </motion.p>
          </div>
          
          <motion.button
            initial={{ opacity: 0, x: 20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: 0.3 }}
            onClick={() => setCurrentPage("programs")}
            className="flex items-center gap-2.5 text-[var(--brand-green)] hover:text-[var(--brand-green-light)] transition-all px-5 py-2.5 rounded-xl border border-[var(--brand-green)]/20 hover:border-[var(--brand-green)]/40 hover:bg-[var(--brand-green)]/5 whitespace-nowrap font-semibold"
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.98 }}
          >
            <span>كل البرامج</span>
            <ArrowLeft className="w-4 h-4" />
          </motion.button>
        </div>

        {/* شبكة المشاريع الحية */}
        <AnimatePresence mode="wait">
          {isLoading ? (
            <motion.div
              key="loading"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              <ProjectsSkeleton />
            </motion.div>
          ) : (
            <motion.div
              key="content"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="grid grid-cols-1 md:grid-cols-2 gap-8"
            >
              {projectItems.map((program, i) => (
                <ProjectCard 
                  key={program.id || i} 
                  program={program} 
                  index={i} 
                  setCurrentPage={setCurrentPage} 
                />
              ))}
            </motion.div>
          )}
        </AnimatePresence>

        {/* زر عرض المزيد */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.5 }}
          className="text-center mt-16"
        >
          <button
            onClick={() => setCurrentPage("projects")}
            className="inline-flex items-center gap-3 px-8 py-4 rounded-2xl bg-gradient-to-r from-[var(--brand-green)] to-[var(--brand-green)]/80 text-white font-semibold hover:shadow-xl transition-all duration-300 hover:scale-105"
          >
            <BarChart3 className="w-5 h-5" />
            <span>استعرض جميع المشاريع</span>
            <ArrowLeft className="w-5 h-5" />
          </button>
        </motion.div>
      </div>
    </section>
  );
}

// Quick Donation Component - Interactive Impact Calculator with Inline Payment
import { motion } from "framer-motion";
import { Heart, Package, CreditCard, Smartphone, Banknote, Users, Droplets, GraduationCap } from "lucide-react";
import { useState, useEffect } from "react";

import { paymentGateway, BANK_ACCOUNTS } from "@/shared/services/payment-gateway.service";
import { useSEO } from "@/utils/seoAdvanced";

interface QuickDonationProps {
  readonly onClose?: () => void;
  readonly embedded?: boolean;
}

interface ImpactResult {
  beneficiaries: number;
  meals: number;
  waterDays: number;
  educationDays: number;
  orphansSupported: number;
}

// Project impact multipliers
const IMPACT_MULTIPLIERS: Record<string, (amount: number) => ImpactResult> = {
  general: (amount) => ({
    beneficiaries: Math.floor(amount / 15),
    meals: Math.floor(amount / 2),
    waterDays: 0,
    educationDays: 0,
    orphansSupported: 0,
  }),
  food: (amount) => ({
    beneficiaries: Math.floor(amount / 10),
    meals: Math.floor(amount / 1.5),
    waterDays: 0,
    educationDays: 0,
    orphansSupported: 0,
  }),
  water: (amount) => ({
    beneficiaries: 0,
    meals: 0,
    waterDays: Math.floor(amount / 25),
    educationDays: 0,
    orphansSupported: 0,
  }),
  education: (amount) => ({
    beneficiaries: 0,
    meals: 0,
    waterDays: 0,
    educationDays: Math.floor(amount / 30),
    orphansSupported: 0,
  }),
  orphans: (amount) => ({
    beneficiaries: 0,
    meals: 0,
    waterDays: 0,
    educationDays: 0,
    orphansSupported: Math.floor(amount / 100),
  }),
  zakat: (amount) => ({
    beneficiaries: Math.floor(amount / 5),
    meals: Math.floor(amount / 2),
    waterDays: 0,
    educationDays: 0,
    orphansSupported: 0,
  }),
};

const PROJECTS = [
  { id: "general", label: "الصندوق العام", icon: Heart, description: "مساهمة عامة في جميع برامج المؤسسة" },
  { id: "food", label: "السلال الغذائية", icon: Package, description: "توفير سلال غذائية للأسر المحتاجة" },
  { id: "water", label: "مشروع الآبار", icon: Droplets, description: "حفر آبار وتوفير مياه شرب نظيفة" },
  { id: "education", label: "التعليم والقرآن", icon: GraduationCap, description: "دعم التعليم وتحفيز القرآن" },
  { id: "orphans", label: "كفالة الأيتام", icon: Users, description: "رعاية يتيم في التعليم والصحة" },
  { id: "zakat", label: "زكاة المال", icon: Banknote, description: "صرف الزكاة في مصارفها الشرعية" },
];

const PAYMENT_METHODS = [
  { id: "stripe", label: "بطاقة ائتمان", icon: CreditCard },
  { id: "bank", label: "تحويل بنكي", icon: Banknote },
  { id: "cash", label: "نقدي", icon: Banknote },
];

export function QuickDonation({ onClose, embedded = false }: QuickDonationProps) {
  const [amount, setAmount] = useState(50);
  const [selectedProject, setSelectedProject] = useState("general");
  const [paymentMethod, setPaymentMethod] = useState("stripe");
  const [donorName, setDonorName] = useState("");
  const [donorEmail, setDonorEmail] = useState("");
  const [donorPhone, setDonorPhone] = useState("");
  const [impact, setImpact] = useState<ImpactResult>({
    beneficiaries: 0,
    meals: 0,
    waterDays: 0,
    educationDays: 0,
    orphansSupported: 0,
  });
  const [isProcessing, setIsProcessing] = useState(false);
  const [showPaymentResult, setShowPaymentResult] = useState(false);
  const [paymentResult, setPaymentResult] = useState<{ success: boolean; message: string; transactionId?: string } | null>(null);

  useSEO({
    title: "تبرع سريع - رحماء بينهم",
    description: "تبرع بسهولة وأثر مباشر في مشاريع المؤسسة",
  });

  useEffect(() => {
    const multiplier = IMPACT_MULTIPLIERS[selectedProject] || IMPACT_MULTIPLIERS.general;
    setImpact(multiplier(amount));
  }, [amount, selectedProject]);

  const handleDonate = async () => {
    setIsProcessing(true);
    setPaymentResult(null);

    try {
      // استخدام payment gateway الحقيقي
      const result = await paymentGateway.initiatePayment({
        amount: amount,
        currency: 'USD',
        method: paymentMethod as any,
        type: selectedProject === 'zakat' ? 'zakat' : 'once',
        projectId: selectedProject,
        donorName: donorName || 'متبرع كريم',
        donorEmail: donorEmail,
        donorPhone: donorPhone,
        description: `تبرع لمشروع ${PROJECTS.find(p => p.id === selectedProject)?.label || 'عام'}`,
      });

      if (result.status === 'completed' || result.status === 'processing') {
        setPaymentResult({
          success: true,
          message: 'تم إنشاء طلب التبرع بنجاح!',
          transactionId: result.transactionId,
        });
        setShowPaymentResult(true);
      } else if (result.status === 'pending') {
        // عرض تفاصيل التحويل البنكي أو النقدي
        const bankAccounts = BANK_ACCOUNTS || [];
        const bankInfo = bankAccounts.length > 0 
          ? `إلى حساب ${bankAccounts[0].accountName} - ${bankAccounts[0].iban}`
          : 'وسيقوم فريقنا بالتواصل معك';
        setPaymentResult({
          success: true,
          message: `يرجى إجراء التحويل البنكي ${bankInfo}`,
          transactionId: result.transactionId,
        });
        setShowPaymentResult(true);
      } else {
        setPaymentResult({
          success: false,
          message: result.confirmationCode || 'فشل في إنشاء طلب التبرع',
        });
        setShowPaymentResult(true);
      }
    } catch (error) {
      setPaymentResult({
        success: false,
        message: error instanceof Error ? error.message : 'حدث خطأ أثناء معالجة الدفع',
      });
      setShowPaymentResult(true);
    } finally {
      setIsProcessing(false);
    }
  };

  const presetAmounts = [10, 25, 50, 100, 250, 500, 1000];

  const content = (
    <div className="max-w-2xl mx-auto" dir="rtl">
      {/* Payment Success/Error Message */}
      {showPaymentResult && paymentResult && (
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className={`mb-6 p-6 rounded-xl text-center ${
            paymentResult.success ? 'bg-green-50 border border-green-200' : 'bg-red-50 border border-red-200'
          }`}
        >
          <div className="text-lg font-semibold mb-2">
            {paymentResult.success ? '✅ نجح التبرع!' : '❌ فشل التبرع'}
          </div>
          <p className="text-gray-600 mb-3">{paymentResult.message}</p>
          {paymentResult.transactionId && (
            <p className="text-sm text-gray-500">رقم المعاملة: {paymentResult.transactionId}</p>
          )}
          <button
            onClick={() => setShowPaymentResult(false)}
            className="mt-4 px-6 py-2 bg-[var(--brand-green)] text-white rounded-lg hover:bg-[var(--brand-green-light)] transition-colors"
          >
            تبرع جديد
          </button>
        </motion.div>
      )}

      <div className="text-center mb-8">
        <Heart className="w-16 h-16 mx-auto mb-4 text-[var(--brand-green)]" />
        <h2 className="text-3xl font-bold mb-2">تبرع سريع وأثر مباشر</h2>
        <p className="text-gray-600">اختر المشروع وحساب أثر تبرعك قبل الدفع</p>
      </div>

      <div className="card p-8">
        {/* Donor Information */}
        <div className="mb-6">
          <span className="block text-lg font-semibold mb-3">المعلومات الشخصية</span>
          <div className="space-y-4">
            <input
              type="text"
              value={donorName}
              onChange={(e) => setDonorName(e.target.value)}
              placeholder="اسم المتبرع (اختياري)"
              className="w-full p-4 border-2 border-gray-200 rounded-lg text-lg focus:border-[var(--brand-green)]"
              dir="rtl"
            />
            <input
              type="email"
              value={donorEmail}
              onChange={(e) => setDonorEmail(e.target.value)}
              placeholder="البريد الإلكتروني (لإرسال الإيصال)"
              className="w-full p-4 border-2 border-gray-200 rounded-lg text-lg focus:border-[var(--brand-green)]"
              dir="ltr"
            />
            <input
              type="tel"
              value={donorPhone}
              onChange={(e) => setDonorPhone(e.target.value)}
              placeholder="رقم الهاتف (اختياري)"
              className="w-full p-4 border-2 border-gray-200 rounded-lg text-lg focus:border-[var(--brand-green)]"
              dir="ltr"
            />
          </div>
        </div>

        {/* Project Selection */}
        <div className="mb-6" role="group" aria-label="اختر المشروع">
          <span className="block text-lg font-semibold mb-3">اختر المشروع</span>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {PROJECTS.map((project) => (
              <button
                key={project.id}
                onClick={() => setSelectedProject(project.id)}
                className={`p-4 rounded-lg border-2 transition-all flex flex-col items-center gap-2 ${
                  selectedProject === project.id
                    ? "border-[var(--brand-green)] bg-[var(--brand-green-pale)]"
                    : "border-gray-200 hover:border-[var(--brand-green)]"
                }`}
                role="radio"
                aria-checked={selectedProject === project.id}
              >
                <project.icon className="w-8 h-8 text-[var(--brand-green)]" />
                <span className="text-sm font-medium">{project.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Amount Selection */}
        <div className="mb-6" role="group" aria-label="قيمة التبرع">
          <span className="block text-lg font-semibold mb-3">قيمة التبرع (ر.ي)</span>
          <div className="grid grid-cols-4 gap-2 mb-3">
            {presetAmounts.map((preset) => (
              <button
                key={preset}
                onClick={() => setAmount(preset)}
                className={`p-3 rounded-lg border transition-all ${
                  amount === preset
                    ? "border-[var(--brand-green)] bg-[var(--brand-green)] text-white"
                    : "border-gray-200 hover:border-[var(--brand-green)]"
                }`}
                role="radio"
                aria-checked={amount === preset}
              >
                {preset}
              </button>
            ))}
          </div>
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(Number(e.target.value))}
            className="w-full p-4 border-2 border-gray-200 rounded-lg text-lg focus:border-[var(--brand-green)]"
            placeholder="أو أدخل مبلغ آخر"
            min="1"
            max="10000"
            dir="ltr"
          />
        </div>

        {/* Payment Method */}
        <div className="mb-8" role="group" aria-label="طريقة الدفع">
          <span className="block text-lg font-semibold mb-3">طريقة الدفع</span>
          <div className="flex gap-3">
            {PAYMENT_METHODS.map((method) => (
              <button
                key={method.id}
                onClick={() => setPaymentMethod(method.id)}
                className={`flex-1 p-3 rounded-lg border-2 transition-all flex items-center justify-center gap-2 ${
                  paymentMethod === method.id
                    ? "border-[var(--brand-green)] bg-[var(--brand-green-pale)]"
                    : "border-gray-200"
                }`}
              >
                <method.icon className="w-5 h-5" />
                <span className="text-sm">{method.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Impact Calculator */}
        <div className="bg-gradient-to-r from-[var(--brand-green)]/5 to-[var(--brand-gold)]/5 p-6 rounded-lg mb-8">
          <h3 className="text-xl font-bold mb-4 text-center">أثر تبرعك</h3>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            {impact.beneficiaries > 0 && (
              <div className="text-center">
                <Users className="w-10 h-10 mx-auto mb-2 text-[var(--brand-green)]" />
                <div className="text-2xl font-bold">{impact.beneficiaries}</div>
                <div className="text-sm text-gray-600">مستفيد</div>
              </div>
            )}
            {impact.meals > 0 && (
              <div className="text-center">
                <Package className="w-10 h-10 mx-auto mb-2 text-[var(--brand-green)]" />
                <div className="text-2xl font-bold">{impact.meals}</div>
                <div className="text-sm text-gray-600">وجبة غذائية</div>
              </div>
            )}
            {impact.waterDays > 0 && (
              <div className="text-center">
                <Droplets className="w-10 h-10 mx-auto mb-2 text-[var(--brand-green)]" />
                <div className="text-2xl font-bold">{impact.waterDays}</div>
                <div className="text-sm text-gray-600">يوم مياه نظيفة</div>
              </div>
            )}
            {impact.educationDays > 0 && (
              <div className="text-center">
                <GraduationCap className="w-10 h-10 mx-auto mb-2 text-[var(--brand-green)]" />
                <div className="text-2xl font-bold">{impact.educationDays}</div>
                <div className="text-sm text-gray-600">يوم تعليم</div>
              </div>
            )}
            {impact.orphansSupported > 0 && (
              <div className="text-center">
                <Users className="w-10 h-10 mx-auto mb-2 text-[var(--brand-green)]" />
                <div className="text-2xl font-bold">{impact.orphansSupported}</div>
                <div className="text-sm text-gray-600">يتيم مكفول</div>
              </div>
            )}
          </div>
        </div>

        {/* Donate Button */}
        <motion.button
          onClick={handleDonate}
          disabled={isProcessing}
          className="w-full btn-primary py-4 rounded-lg text-xl font-bold flex items-center justify-center gap-2 disabled:opacity-50"
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
        >
          {isProcessing ? (
            <>
              <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
              جاري المعالجة...
            </>
          ) : (
            <>
              <Heart className="w-6 h-6" fill="white" />
              تبرع الآن - {amount} ر.ي
            </>
          )}
        </motion.button>
      </div>
    </div>
  );

  if (embedded) {
    return content;
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl max-h-[90vh] overflow-y-auto relative w-full max-w-3xl">
        <button
          onClick={onClose}
          className="absolute top-4 left-4 p-2 rounded-lg hover:bg-gray-100"
        >
          ✕
        </button>
        <div className="p-6">{content}</div>
      </div>
    </div>
  );
}

import React, { useEffect } from 'react';
import { Type, Sun, Moon, Coffee, Eye, RotateCcw, AlignJustify, Sparkles } from 'lucide-react';

export type FontSizeLevel = 'normal' | 'large' | 'xlarge' | 'xxlarge';
export type ReaderThemeMode = 'light' | 'sepia' | 'dark' | 'contrast';
export type LineHeightMode = 'normal' | 'relaxed' | 'loose';

export interface ReadabilityState {
  fontSize: FontSizeLevel;
  theme: ReaderThemeMode;
  lineHeight?: LineHeightMode;
}

interface ReadabilityControlsProps {
  fontSize: FontSizeLevel;
  theme: ReaderThemeMode;
  lineHeight?: LineHeightMode;
  onFontSizeChange: (size: FontSizeLevel) => void;
  onThemeChange: (theme: ReaderThemeMode) => void;
  onLineHeightChange?: (height: LineHeightMode) => void;
  onReset?: () => void;
  className?: string;
  showLabels?: boolean;
}

export const FONT_SIZE_CLASSES: Record<FontSizeLevel, string> = {
  normal: 'text-base sm:text-lg',
  large: 'text-lg sm:text-xl',
  xlarge: 'text-xl sm:text-2xl',
  xxlarge: 'text-2xl sm:text-3xl',
};

export const LINE_HEIGHT_CLASSES: Record<LineHeightMode, string> = {
  normal: 'leading-[1.95]',
  relaxed: 'leading-[2.25]',
  loose: 'leading-[2.55]',
};

export const READER_THEME_CLASSES: Record<ReaderThemeMode, string> = {
  light: 'bg-white text-slate-800 border-slate-200',
  sepia: 'bg-[#FAF5E8] text-[#3A2F1D] border-[#E8DFC8]',
  dark: 'bg-[#0F172A] text-slate-100 border-slate-800',
  contrast: 'bg-black text-[#FACC15] border-yellow-500 font-semibold',
};

export const READER_CARD_THEME_CLASSES: Record<ReaderThemeMode, string> = {
  light: 'bg-slate-50 border-slate-200 text-slate-800',
  sepia: 'bg-[#F2EBD9] border-[#E2D8C0] text-[#3A2F1D]',
  dark: 'bg-[#1E293B] border-slate-700 text-slate-200',
  contrast: 'bg-zinc-900 border-yellow-400 text-[#FACC15]',
};

export const READER_TOOLBAR_CLASSES: Record<ReaderThemeMode, string> = {
  light: 'bg-slate-100/90 text-slate-700 border-slate-200',
  sepia: 'bg-[#EFE6D1]/90 text-[#3A2F1D] border-[#DFCFA8]',
  dark: 'bg-slate-800/90 text-slate-200 border-slate-700',
  contrast: 'bg-zinc-900/90 text-yellow-300 border-yellow-500',
};

const STORAGE_KEYS = {
  fontSize: 'rh_reader_fontSize',
  theme: 'rh_reader_theme',
  lineHeight: 'rh_reader_lineHeight',
};

export const getSavedReaderPreferences = (): ReadabilityState => {
  try {
    const savedFontSize = localStorage.getItem(STORAGE_KEYS.fontSize) as FontSizeLevel;
    const savedTheme = localStorage.getItem(STORAGE_KEYS.theme) as ReaderThemeMode;
    const savedLineHeight = localStorage.getItem(STORAGE_KEYS.lineHeight) as LineHeightMode;

    return {
      fontSize: savedFontSize && ['normal', 'large', 'xlarge', 'xxlarge'].includes(savedFontSize) ? savedFontSize : 'normal',
      theme: savedTheme && ['light', 'sepia', 'dark', 'contrast'].includes(savedTheme) ? savedTheme : 'light',
      lineHeight: savedLineHeight && ['normal', 'relaxed', 'loose'].includes(savedLineHeight) ? savedLineHeight : 'relaxed',
    };
  } catch {
    return { fontSize: 'normal', theme: 'light', lineHeight: 'relaxed' };
  }
};

export const saveReaderPreferences = (state: Partial<ReadabilityState>) => {
  try {
    if (state.fontSize) localStorage.setItem(STORAGE_KEYS.fontSize, state.fontSize);
    if (state.theme) localStorage.setItem(STORAGE_KEYS.theme, state.theme);
    if (state.lineHeight) localStorage.setItem(STORAGE_KEYS.lineHeight, state.lineHeight);
  } catch {
    // ignore
  }
};

export const ReadabilityControls: React.FC<ReadabilityControlsProps> = ({
  fontSize,
  theme,
  lineHeight = 'relaxed',
  onFontSizeChange,
  onThemeChange,
  onLineHeightChange,
  onReset,
  className = '',
  showLabels = true,
}) => {
  const fontSizes: { key: FontSizeLevel; label: string; tooltip: string; sizeDisplay: string }[] = [
    { key: 'normal', label: 'أ', tooltip: 'حجم عادي (١٠٠٪)', sizeDisplay: 'text-xs' },
    { key: 'large', label: 'أ+', tooltip: 'حجم مريح (١٢٠٪)', sizeDisplay: 'text-sm font-semibold' },
    { key: 'xlarge', label: 'أ++', tooltip: 'حجم كبير (١٤٠٪)', sizeDisplay: 'text-base font-bold' },
    { key: 'xxlarge', label: 'أ+++', tooltip: 'حجم أقصى (١٦٥٪)', sizeDisplay: 'text-lg font-black' },
  ];

  const themes: { key: ReaderThemeMode; label: string; icon: React.ReactNode; bgClass: string }[] = [
    { key: 'light', label: 'نهاري', icon: <Sun className="w-3.5 h-3.5" />, bgClass: 'bg-white text-slate-800 border-slate-300' },
    { key: 'sepia', label: 'دافئ', icon: <Coffee className="w-3.5 h-3.5" />, bgClass: 'bg-[#FAF5E8] text-[#3D3222] border-[#E0D5BC]' },
    { key: 'dark', label: 'ليلي', icon: <Moon className="w-3.5 h-3.5" />, bgClass: 'bg-slate-900 text-slate-100 border-slate-700' },
    { key: 'contrast', label: 'تباين عالي', icon: <Eye className="w-3.5 h-3.5" />, bgClass: 'bg-black text-yellow-300 border-yellow-400 font-bold' },
  ];

  const lineHeights: { key: LineHeightMode; label: string; tooltip: string }[] = [
    { key: 'normal', label: 'مضغوط', tooltip: 'تباعد أسطر عادي' },
    { key: 'relaxed', label: 'مريح', tooltip: 'تباعد أسطر مريح للقراءة' },
    { key: 'loose', label: 'واسع', tooltip: 'تباعد أسطر واسع' },
  ];

  const handleFontSize = (size: FontSizeLevel) => {
    onFontSizeChange(size);
    saveReaderPreferences({ fontSize: size });
  };

  const handleTheme = (t: ReaderThemeMode) => {
    onThemeChange(t);
    saveReaderPreferences({ theme: t });
  };

  const handleLineHeight = (lh: LineHeightMode) => {
    if (onLineHeightChange) {
      onLineHeightChange(lh);
      saveReaderPreferences({ lineHeight: lh });
    }
  };

  return (
    <div 
      className={`flex flex-wrap items-center gap-2 p-1.5 rounded-2xl bg-slate-500/10 backdrop-blur-md border border-slate-300/30 font-cairo ${className}`}
      role="toolbar"
      aria-label="خيارات القراءة المريحة والتحكم بالخط والتباين"
    >
      {/* Feature Label */}
      {showLabels && (
        <div className="hidden lg:flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-[var(--brand-green)]/10 text-[var(--brand-green)] text-xs font-bold shrink-0">
          <Sparkles className="w-3.5 h-3.5 text-[#C69E5A]" />
          <span>القراءة المريحة:</span>
        </div>
      )}

      {/* Font Size Selector */}
      <div 
        className="flex items-center bg-slate-200/60 dark:bg-slate-800/80 p-0.5 rounded-xl border border-slate-300/30"
        role="group"
        aria-label="تغيير حجم الخط"
      >
        <span className="sr-only">حجم الخط:</span>
        <Type className="w-3.5 h-3.5 mx-1.5 opacity-60 shrink-0" aria-hidden="true" />
        {fontSizes.map((item) => (
          <button
            key={item.key}
            onClick={() => handleFontSize(item.key)}
            className={`px-2 py-1 rounded-lg transition-all text-xs font-bold ${
              fontSize === item.key
                ? 'bg-white text-[var(--brand-green)] shadow-xs scale-105'
                : 'opacity-60 hover:opacity-100 text-slate-700 hover:text-slate-900'
            } ${item.sizeDisplay}`}
            title={item.tooltip}
            aria-pressed={fontSize === item.key}
            aria-label={item.tooltip}
          >
            {item.label}
          </button>
        ))}
      </div>

      {/* Theme & Contrast Selector */}
      <div 
        className="flex items-center bg-slate-200/60 dark:bg-slate-800/80 p-0.5 rounded-xl border border-slate-300/30"
        role="group"
        aria-label="تغيير تباين وألوان القراءة"
      >
        {themes.map((t) => (
          <button
            key={t.key}
            onClick={() => handleTheme(t.key)}
            className={`p-1.5 sm:px-2 py-1 rounded-lg text-xs font-bold flex items-center gap-1 transition-all border ${t.bgClass} ${
              theme === t.key
                ? 'ring-2 ring-[var(--brand-green)] shadow-xs scale-105'
                : 'opacity-70 hover:opacity-100 border-transparent'
            }`}
            title={`نمط الألوان والتباين: ${t.label}`}
            aria-pressed={theme === t.key}
            aria-label={`نمط الألوان: ${t.label}`}
          >
            {t.icon}
            <span className="hidden sm:inline text-[11px]">{t.label}</span>
          </button>
        ))}
      </div>

      {/* Line Height Selector (Optional) */}
      {onLineHeightChange && (
        <div 
          className="hidden md:flex items-center bg-slate-200/60 dark:bg-slate-800/80 p-0.5 rounded-xl border border-slate-300/30"
          role="group"
          aria-label="تباعد الأسطر"
        >
          <AlignJustify className="w-3.5 h-3.5 mx-1.5 opacity-60 shrink-0" aria-hidden="true" />
          {lineHeights.map((lh) => (
            <button
              key={lh.key}
              onClick={() => handleLineHeight(lh.key)}
              className={`px-2 py-1 rounded-lg text-[11px] font-bold transition-all ${
                lineHeight === lh.key
                  ? 'bg-white text-[var(--brand-green)] shadow-xs'
                  : 'opacity-60 hover:opacity-100 text-slate-700'
              }`}
              title={lh.tooltip}
              aria-pressed={lineHeight === lh.key}
              aria-label={lh.tooltip}
            >
              {lh.label}
            </button>
          ))}
        </div>
      )}

      {/* Reset Button */}
      {onReset && (
        <button
          onClick={onReset}
          className="p-1.5 rounded-xl opacity-60 hover:opacity-100 hover:bg-slate-200/60 transition-all text-xs font-semibold text-slate-700"
          title="إعادة ضبط إعدادات القراءة الافتراضية"
          aria-label="إعادة ضبط القراءة"
        >
          <RotateCcw className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  );
};

