import { useEffect, useState, useCallback } from 'react';

interface DataLoaderOptions {
  staleWhileRevalidate?: boolean;
  cacheTime?: number; // بالثواني
  retryCount?: number;
  retryDelay?: number;
  timeout?: number;
}

interface DataLoaderResult<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
  refetch: () => void;
}

/**
 * Hook مخصص لتحميل البيانات مع دعم إعادة المحاولة والتخزين المؤقت
 */
export function useDataLoader<T>(
  fetchFn: () => Promise<T>,
  dependencies: any[] = [],
  options: DataLoaderOptions = {}
): DataLoaderResult<T> {
  const {
    staleWhileRevalidate = false,
    cacheTime = 5 * 60, // 5 دقائق افتراضياً
    retryCount = 3,
    retryDelay = 1000,
    timeout = 15000
  } = options;

  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const cacheKey = `rbdcye_data_${dependencies.join('_')}`;

  // تحميل البيانات من التخزين المؤقت
  const loadFromCache = useCallback(() => {
    try {
      const cached = localStorage.getItem(cacheKey);
      if (cached) {
        const { timestamp, value } = JSON.parse(cached);
        const age = (Date.now() - timestamp) / 1000;
        
        // إذا كانت البيانات لا تزال صالحة
        if (age < cacheTime) {
          return value as T;
        }
      }
    } catch (e) {
      console.warn('Failed to load from cache:', e);
      localStorage.removeItem(cacheKey);
    }
    return null;
  }, [cacheKey, cacheTime]);

  // حفظ البيانات في التخزين المؤقت
  const saveToCache = useCallback((value: T) => {
    try {
      const cacheData = {
        timestamp: Date.now(),
        value
      };
      localStorage.setItem(cacheKey, JSON.stringify(cacheData));
    } catch (e) {
      console.warn('Failed to save to cache:', e);
    }
  }, [cacheKey]);

  const fetchData = useCallback(async () => {
    let mounted = true;
    const abortController = new AbortController();

    // محاولة تحميل من التخزين المؤقت أولاً إذا كان staleWhileRevalidate
    if (staleWhileRevalidate) {
      const cached = loadFromCache();
      if (cached) {
        setData(cached);
      }
    }

    setLoading(true);
    setError(null);

    // إعادة المحاولة
    for (let attempt = 0; attempt < retryCount; attempt++) {
      try {
        const result = await Promise.race([
          fetchFn(),
          new Promise<never>((_, reject) => 
            setTimeout(() => {
              abortController.abort();
              reject(new Error('Timeout'));
            }, timeout)
          )
        ]);
        
        if (!mounted) return;
        
        setData(result);
        saveToCache(result);
        setError(null);
        return;
      } catch (err) {
        const error = err as Error;
        
        // إذا كان ذلك آخر محاولة
        if (attempt === retryCount - 1) {
          if (!mounted) return;
          
          setError(error);
          
          // محاولة استخدام البيانات من التخزين المؤقت
          if (!staleWhileRevalidate) {
            const cached = loadFromCache();
            if (cached) {
              setData(cached);
              setError(null);
            }
          }
        } else {
          // انتظار قبل المحاولة التالية
          await new Promise(resolve => setTimeout(resolve, retryDelay * (attempt + 1)));
        }
      }
    }

    return () => {
      mounted = false;
      abortController.abort();
    };
  }, [fetchFn, loadFromCache, saveToCache, staleWhileRevalidate, retryCount, retryDelay, timeout]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const refetch = useCallback(() => {
    fetchData();
  }, [fetchData]);

  return { data, loading, error, refetch };
}

import { useState, useEffect, useRef } from 'react';

export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
}

export function useThrottle<T extends (...args: any[]) => any>(
  func: T,
  delay: number
): (...args: Parameters<T>) => void {
  const lastRun = useRef(0);
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return (...args: Parameters<T>) => {
    const now = Date.now();
    if (now - lastRun.current >= delay) {
      lastRun.current = now;
      func(...args);
    } else {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
        lastRun.current = Date.now();
        func(...args);
      }, delay - (now - lastRun.current));
    }
  };
}

// Form Validation Hook - Enterprise-grade validation without external dependencies
import { useState, useCallback, useEffect } from 'react';

type ValidationRules<T> = {
  [K in keyof T]?: {
    required?: string;
    min?: { value: number; message: string };
    max?: { value: number; message: string };
    pattern?: { regex: RegExp; message: string };
    email?: string;
    phone?: string;
    url?: string;
    custom?: (value: T[K]) => string | undefined;
  };
};

type ValidationErrors<T> = Partial<Record<keyof T, string>>;

interface UseFormValidationOptions<T> {
  initialValues: T;
  validationRules?: ValidationRules<T>;
  onSubmit: (values: T) => Promise<void> | void;
  sanitize?: boolean;
}

export function useFormValidation<T extends Record<string, any>>({
  initialValues,
  validationRules = {},
  onSubmit,
  sanitize = true
}: UseFormValidationOptions<T>) {
  const [values, setValues] = useState<T>(initialValues);
  const [errors, setErrors] = useState<ValidationErrors<T>>({});
  const [touched, setTouched] = useState<Partial<Record<keyof T, boolean>>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [isDirty, setIsDirty] = useState(false);

  // Reset form when initialValues change
  useEffect(() => {
    setValues(initialValues);
    setErrors({});
    setTouched({});
    setIsDirty(false);
  }, [initialValues]);

  const sanitizeValue = useCallback((value: any): any => {
    if (value === null || value === undefined) return value;
    
    if (typeof value === 'string') {
      // Remove HTML tags and dangerous characters
      return value
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, '')
        .replace(/on\w+\s*=\s*["'][^"']*["']/gi, '')
        .replace(/javascript\s*:/gi, '')
        .trim();
    }
    
    if (typeof value === 'number') {
      return Number.isFinite(value) ? value : 0;
    }
    
    return value;
  }, []);

  const validateField = useCallback((name: keyof T, value: T[keyof T]): string | undefined => {
    const rules = validationRules[name];
    if (!rules) return undefined;

    const stringValue = String(value || '').trim();

    // Required check
    if (rules.required && (!stringValue || stringValue.length === 0)) {
      return rules.required;
    }

    if (!stringValue) return undefined;

    // Min length
    if (rules.min && stringValue.length < rules.min.value) {
      return rules.min.message;
    }

    // Max length
    if (rules.max && stringValue.length > rules.max.value) {
      return rules.max.message;
    }

    // Pattern check
    if (rules.pattern && !rules.pattern.regex.test(stringValue)) {
      return rules.pattern.message;
    }

    // Email check
    if (rules.email) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(stringValue)) {
        return rules.email;
      }
    }

    // Phone check
    if (rules.phone) {
      const phoneRegex = /^\+?[\d]{7,15}$/;
      const cleaned = stringValue.replace(/[^\d+]/g, '');
      if (!phoneRegex.test(cleaned)) {
        return rules.phone;
      }
    }

    // URL check
    if (rules.url) {
      try {
        new URL(stringValue);
      } catch {
        return rules.url;
      }
    }

    // Custom validation
    if (rules.custom) {
      return rules.custom(value);
    }

    return undefined;
  }, [validationRules]);

  const validateAll = useCallback((): boolean => {
    const newErrors: ValidationErrors<T> = {};
    let isValid = true;

    Object.keys(values).forEach((key) => {
      const fieldKey = key as keyof T;
      const error = validateField(fieldKey, values[fieldKey]);
      if (error) {
        newErrors[fieldKey] = error;
        isValid = false;
      }
    });

    setErrors(newErrors);
    setTouched(
      Object.keys(values).reduce((acc, key) => ({ ...acc, [key]: true }), {} as Record<keyof T, boolean>)
    );
    return isValid;
  }, [values, validateField]);

  const handleChange = useCallback((name: keyof T, value: T[keyof T]) => {
    const sanitizedValue = sanitize ? sanitizeValue(value) : value;
    setValues(prev => ({ ...prev, [name]: sanitizedValue }));
    setIsDirty(true);
    
    // Clear error when user starts typing
    if (errors[name]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[name];
        return newErrors;
      });
    }
  }, [errors, sanitize, sanitizeValue]);

  const handleBlur = useCallback((name: keyof T) => {
    setTouched(prev => ({ ...prev, [name]: true }));
    const error = validateField(name, values[name]);
    if (error) {
      setErrors(prev => ({ ...prev, [name]: error }));
    }
  }, [validateField, values]);

  const handleSubmit = useCallback(async (e?: React.FormEvent) => {
    e?.preventDefault();
    
    if (!validateAll()) {
      return;
    }

    setIsSubmitting(true);
    setSubmitError(null);
    setSubmitSuccess(false);

    try {
      await onSubmit(values);
      setSubmitSuccess(true);
      setTimeout(() => {
        setValues(initialValues);
        setTouched({});
        setIsDirty(false);
        setSubmitSuccess(false);
      }, 3000);
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : 'حدث خطأ غير متوقع');
    } finally {
      setIsSubmitting(false);
    }
  }, [values, validateAll, onSubmit, initialValues]);

  const reset = useCallback(() => {
    setValues(initialValues);
    setErrors({});
    setTouched({});
    setIsDirty(false);
    setSubmitSuccess(false);
    setSubmitError(null);
  }, [initialValues]);

  const setFieldValue = useCallback((name: keyof T, value: T[keyof T]) => {
    const sanitizedValue = sanitize ? sanitizeValue(value) : value;
    setValues(prev => ({ ...prev, [name]: sanitizedValue }));
    setIsDirty(true);
  }, [sanitize, sanitizeValue]);

  const getFieldProps = useCallback((name: keyof T) => ({
    value: values[name] || '',
    onChange: (value: T[keyof T]) => handleChange(name, value),
    onBlur: () => handleBlur(name),
    error: touched[name] ? errors[name] : undefined,
  }), [values, errors, touched, handleChange, handleBlur]);

  return {
    values,
    errors,
    touched,
    isSubmitting,
    submitSuccess,
    submitError,
    isDirty,
    handleChange,
    handleBlur,
    handleSubmit,
    reset,
    setFieldValue,
    validateField,
    getFieldProps,
    sanitizeValue,
  };
}

