export function validateFieldValue<T>(
  value: T,
  rules: any
): string | undefined {
  if (!rules) return undefined;

  const stringValue = String(value || '').trim();

  if (rules.required && !stringValue) {
    return rules.required;
  }

  if (!stringValue) return undefined;

  if (rules.min && stringValue.length < rules.min.value) {
    return rules.min.message;
  }

  if (rules.max && stringValue.length > rules.max.value) {
    return rules.max.message;
  }

  if (rules.pattern && !rules.pattern.regex.test(stringValue)) {
    return rules.pattern.message;
  }

  if (rules.email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(stringValue)) {
      return rules.email;
    }
  }

  if (rules.phone) {
    const phoneRegex = /^\+?[\d]{7,15}$/;
    const cleaned = stringValue.replace(/[^\d+]/g, '');
    if (!phoneRegex.test(cleaned)) {
      return rules.phone;
    }
  }

  if (rules.url) {
    try {
      new URL(stringValue);
    } catch {
      return rules.url;
    }
  }

  if (rules.custom) {
    return rules.custom(value);
  }

  return undefined;
}

// Optimistic UI Hook - Instant Feedback for Better UX
import { useState, useCallback, useRef } from 'react';

interface OptimisticState<T> {
  data: T;
  isLoading: boolean;
  error: Error | null;
  isOptimistic: boolean;
}

export function useOptimisticUI<T>(initialData: T) {
  const [state, setState] = useState<OptimisticState<T>>({
    data: initialData,
    isLoading: false,
    error: null,
    isOptimistic: false,
  });
  
  const pendingOperations = useRef<Map<string, { previousData: T; rollback: () => void }>>(new Map());

  const executeOptimistic = useCallback((
    operationId: string,
    optimisticData: T,
    actualOperation: () => Promise<T>,
    rollbackData?: T
  ): Promise<T> => {
    // Store previous data for rollback
    pendingOperations.current.set(operationId, {
      previousData: state.data,
      rollback: () => {
        if (rollbackData) {
          setState(prev => ({ ...prev, data: rollbackData, isOptimistic: false }));
        }
      }
    });

    // Immediately update UI with optimistic data
    setState(prev => ({
      ...prev,
      data: optimisticData,
      isLoading: true,
      error: null,
      isOptimistic: true,
    }));

    return actualOperation()
      .then((result) => {
        // Success - update with real data
        pendingOperations.current.delete(operationId);
        setState(prev => ({
          ...prev,
          data: result,
          isLoading: false,
          isOptimistic: false,
        }));
        return result;
      })
      .catch((error) => {
        // Failure - rollback to previous state
        const pending = pendingOperations.current.get(operationId);
        if (pending) {
          pending.rollback();
          pendingOperations.current.delete(operationId);
        }
        setState(prev => ({
          ...prev,
          isLoading: false,
          isOptimistic: false,
          error,
        }));
        throw error;
      });
  }, [state.data]);

  const updateOptimistic = useCallback((operationId: string, optimisticData: T) => {
    setState(prev => ({
      ...prev,
      data: optimisticData,
      isOptimistic: true,
    }));
  }, []);

  const confirmOptimistic = useCallback((operationId: string) => {
    pendingOperations.current.delete(operationId);
    setState(prev => ({
      ...prev,
      isOptimistic: false,
    }));
  }, []);

  const cancelOptimistic = useCallback((operationId: string, rollbackData: T) => {
    const pending = pendingOperations.current.get(operationId);
    if (pending) {
      pending.rollback();
      pendingOperations.current.delete(operationId);
    } else {
      setState(prev => ({
        ...prev,
        data: rollbackData,
        isOptimistic: false,
      }));
    }
  }, []);

  const clearError = useCallback(() => {
    setState(prev => ({ ...prev, error: null }));
  }, []);

  const reset = useCallback((newData: T) => {
    pendingOperations.current.clear();
    setState({
      data: newData,
      isLoading: false,
      error: null,
      isOptimistic: false,
    });
  }, []);

  return {
    data: state.data,
    isLoading: state.isLoading,
    error: state.error,
    isOptimistic: state.isOptimistic,
    executeOptimistic,
    updateOptimistic,
    confirmOptimistic,
    cancelOptimistic,
    clearError,
    reset,
  };
}

// Hook for batch optimistic updates
export function useBatchOptimistic<T>(initialData: T[]) {
  const [state, setState] = useState<{
    data: T[];
    pending: Set<string>;
    errors: Map<string, Error>;
  }>({
    data: initialData,
    pending: new Set(),
    errors: new Map(),
  });

  const optimisticAdd = useCallback((item: T, operation: () => Promise<T>) => {
    const tempId = `temp_${Date.now()}_${Math.random()}`;
    
    setState(prev => ({
      ...prev,
      data: [...prev.data, { ...item, id: tempId } as any],
      pending: new Set(prev.pending).add(tempId),
    }));

    return operation()
      .then((result) => {
        setState(prev => {
          const newPending = new Set(prev.pending);
          newPending.delete(tempId);
          return {
            ...prev,
            data: prev.data.map(item => (item as any).id === tempId ? result : item),
            pending: newPending,
          };
        });
        return result;
      })
      .catch((error) => {
        setState(prev => {
          const newErrors = new Map(prev.errors);
          newErrors.set(tempId, error);
          return {
            ...prev,
            data: prev.data.filter(item => (item as any).id !== tempId),
            pending: new Set(prev.pending).delete(tempId) ? prev.pending : new Set(prev.pending),
            errors: newErrors,
          };
        });
        throw error;
      });
  }, []);

  const optimisticUpdate = useCallback((
    id: string,
    updates: Partial<T>,
    operation: () => Promise<T>
  ) => {
    const previousItem = state.data.find(item => (item as any).id === id);
    
    setState(prev => ({
      ...prev,
      data: prev.data.map(item => 
        (item as any).id === id ? { ...item, ...updates } : item
      ),
      pending: new Set(prev.pending).add(id),
    }));

    return operation()
      .then((result) => {
        setState(prev => {
          const newPending = new Set(prev.pending);
          newPending.delete(id);
          return {
            ...prev,
            data: prev.data.map(item => (item as any).id === id ? result : item),
            pending: newPending,
          };
        });
        return result;
      })
      .catch((error) => {
        setState(prev => {
          const newPending = new Set(prev.pending);
          newPending.delete(id);
          return {
            ...prev,
            data: prev.data.map(item => 
              (item as any).id === id ? previousItem || item : item
            ),
            pending: newPending,
            errors: new Map(prev.errors).set(id, error),
          };
        });
        throw error;
      });
  }, [state.data]);

  const optimisticDelete = useCallback((id: string, operation: () => Promise<void>) => {
    const previousItem = state.data.find(item => (item as any).id === id);
    
    setState(prev => ({
      ...prev,
      data: prev.data.filter(item => (item as any).id !== id),
      pending: new Set(prev.pending).add(id),
    }));

    return operation()
      .then(() => {
        setState(prev => {
          const newPending = new Set(prev.pending);
          newPending.delete(id);
          return {
            ...prev,
            pending: newPending,
          };
        });
      })
      .catch((error) => {
        setState(prev => {
          const newPending = new Set(prev.pending);
          newPending.delete(id);
          return {
            ...prev,
            data: previousItem ? [...prev.data, previousItem] : prev.data,
            pending: newPending,
            errors: new Map(prev.errors).set(id, error),
          };
        });
        throw error;
      });
  }, [state.data]);

  const retry = useCallback((id: string) => {
    const error = state.errors.get(id);
    if (!error) return Promise.reject(new Error('No error to retry'));

    state.errors.delete(id);
    // Return a rejected promise to allow caller to handle retry
    return Promise.reject(error);
  }, [state.errors]);

  return {
    data: state.data,
    pending: Array.from(state.pending),
    errors: Array.from(state.errors.entries()),
    optimisticAdd,
    optimisticUpdate,
    optimisticDelete,
    retry,
    clearError: (id?: string) => {
      if (id) {
        state.errors.delete(id);
      } else {
        state.errors.clear();
      }
    },
  };
}

// ============================================================
// useOptimizedFetch Hook - optimized fetching with caching and deduplication
// ============================================================
import { useState, useEffect, useCallback, useRef, memo } from 'react';

interface CacheEntry<T> {
  data: T;
  timestamp: number;
  promise?: Promise<T>;
}

const globalCache = new Map<string, CacheEntry<any>>();
const pendingRequests = new Map<string, Promise<any>>();

export function useOptimizedFetch<T>(
  key: string,
  fetcher: () => Promise<T>,
  options: {
    ttl?: number;
    staleTime?: number;
    immediate?: boolean;
  } = {}
): { data: T | null; loading: boolean; error: string | null; refetch: () => void } {
  const { ttl = 5 * 60 * 1000, staleTime = 60 * 1000, immediate = true } = options;
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const mountedRef = useRef(true);

  const fetchData = useCallback(async () => {
    const now = Date.now();
    const cached = globalCache.get(key);

    // Return stale data immediately if available
    if (cached && now - cached.timestamp < ttl + staleTime) {
      if (!mountedRef.current) return;
      setData(cached.data);

      // Background refresh if stale
      if (now - cached.timestamp > ttl && !cached.promise) {
        const promise = fetcher().catch(() => {});
        cached.promise = promise;
        pendingRequests.set(key, promise);

        promise.then(result => {
          if (mountedRef.current) {
            setData(result as T);
            globalCache.set(key, { data: result, timestamp: Date.now() });
          }
        }).finally(() => {
          pendingRequests.delete(key);
        });
      }
      return;
    }

    // Deduplicate in-flight requests
    if (pendingRequests.has(key)) {
      try {
        const result = await pendingRequests.get(key)!;
        if (mountedRef.current) setData(result as T);
      } catch {
        // Ignore dedup errors
      }
      return;
    }

    // Fetch new data
    setLoading(true);
    setError(null);

    const promise = fetcher();
    pendingRequests.set(key, promise);

    promise
      .then(result => {
        if (mountedRef.current) {
          setData(result as T);
          globalCache.set(key, { data: result, timestamp: Date.now() });
        }
      })
      .catch((err: any) => {
        if (mountedRef.current) {
          setError(err?.message || 'حدث خطأ');
        }
      })
      .finally(() => {
        pendingRequests.delete(key);
        if (mountedRef.current) setLoading(false);
      });

    return promise;
  }, [key, fetcher, ttl, staleTime]);

  useEffect(() => {
    mountedRef.current = true;
    if (immediate) fetchData();

    return () => {
      mountedRef.current = false;
    };
  }, [immediate, fetchData]);

  return { data, loading, error, refetch: fetchData };
}

// Optimize re-renders with memo comparison
export function createOptimizedComponent<T extends object>(
  Component: React.FC<T>,
  areEqual?: (prev: T, next: T) => boolean
) {
  return memo(Component, areEqual);
}

import { useState, useEffect, useCallback } from 'react';

interface UseOptimizedImageOptions {
  src: string;
  alt?: string;
  placeholder?: string;
  threshold?: number;
  rootMargin?: string;
}

interface UseOptimizedImageResult {
  src: string;
  isLoading: boolean;
  isError: boolean;
  error: Error | null;
  imgRef: (node: HTMLImageElement | null) => void;
}

export function useOptimizedImage({
  src,
  alt = '',
  placeholder = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300"%3E%3Crect fill="%23e5e7eb" width="400" height="300"/%3E%3C/svg%3E',
  threshold = 0.1,
  rootMargin = '50px',
}: UseOptimizedImageOptions): UseOptimizedImageResult {
  const [currentSrc, setCurrentSrc] = useState(placeholder);
  const [isLoading, setIsLoading] = useState(true);
  const [isError, setIsError] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [imgRef, setImgRef] = useState<HTMLImageElement | null>(null);

  const handleLoad = useCallback(() => {
    setIsLoading(false);
    setIsError(false);
    setError(null);
  }, []);

  const handleError = useCallback(() => {
    setIsLoading(false);
    setIsError(true);
    setError(new Error(`Failed to load image: ${src}`));
  }, [src]);

  useEffect(() => {
    if (!src || !imgRef) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setCurrentSrc(src);
            observer.disconnect();
          }
        });
      },
      { threshold, rootMargin }
    );

    observer.observe(imgRef);
    return () => observer.disconnect();
  }, [src, threshold, rootMargin, imgRef]);

  useEffect(() => {
    if (!imgRef) return;

    if (currentSrc !== placeholder) {
      setIsLoading(true);
      setIsError(false);
      setError(null);
    }
  }, [currentSrc, imgRef, placeholder]);

  useEffect(() => {
    if (!imgRef || currentSrc === placeholder) return;

    if (imgRef.complete && imgRef.naturalWidth > 0) {
      handleLoad();
    }
  }, [imgRef, currentSrc, placeholder, handleLoad]);

  return {
    src: currentSrc,
    isLoading,
    isError,
    error,
    imgRef: setImgRef,
  };
}

export function createOptimizedImageSrc(src: string, width: number, quality = 80): string {
  if (!src) return src;

  const separator = src.includes('?') ? '&' : '?';
  const params = new URLSearchParams();

  if (src.includes('unsplash.com')) {
    params.set('w', String(width));
    params.set('q', String(quality));
    params.set('auto', 'format');
    params.set('fit', 'crop');
    return `${src}${separator}${params.toString()}`;
  }

  if (src.includes('images.pexels.com')) {
    params.set('w', String(width));
    return `${src}${separator}${params.toString()}`;
  }

  return src;
}

export function preloadImage(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve();
    img.onerror = reject;
    img.src = src;
  });
}

// Smart Toolbar Hook - Performance Optimized Interactions
import { useState, useEffect, useRef, useCallback, useMemo } from 'react';

interface ToolbarPreferences {
  position: { x: number; y: number };
  visible: boolean;
  expanded: boolean;
  usageStats: Record<string, number>;
}

const STORAGE_KEY = 'smart-toolbar-preferences';

// Get stored preferences
function getStoredPreferences(): ToolbarPreferences {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch (e) {
    // Ignore errors
  }
  return {
    position: { x: 0, y: 0 },
    visible: true,
    expanded: false,
    usageStats: {},
  };
}

// Save preferences to storage
function savePreferences(prefs: Partial<ToolbarPreferences>) {
  try {
    const current = getStoredPreferences();
    const updated = { ...current, ...prefs };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  } catch (e) {
    // Ignore errors
  }
}

export function useSmartToolbar() {
  const [preferences, setPreferences] = useState<ToolbarPreferences>(getStoredPreferences);
  const positionRef = useRef(preferences.position);

  // Throttled position update
  const updatePosition = useCallback((x: number, y: number) => {
    const newPosition = {
      x: Math.max(-200, Math.min(window.innerWidth - 200, x)),
      y: Math.max(0, Math.min(window.innerHeight - 100, y)),
    };
    
    positionRef.current = newPosition;
    setPreferences(prev => ({ ...prev, position: newPosition }));
    savePreferences({ position: newPosition });
  }, []);

  // Toggle visibility
  const toggleVisibility = useCallback((visible?: boolean) => {
    const newVisible = visible ?? !preferences.visible;
    setPreferences(prev => ({ ...prev, visible: newVisible }));
    savePreferences({ visible: newVisible });
  }, [preferences.visible]);

  // Toggle expanded state
  const toggleExpanded = useCallback((expanded?: boolean) => {
    const newExpanded = expanded ?? !preferences.expanded;
    setPreferences(prev => ({ ...prev, expanded: newExpanded }));
    savePreferences({ expanded: newExpanded });
  }, [preferences.expanded]);

  // Track action usage
  const trackActionUsage = useCallback((actionId: string) => {
    setPreferences(prev => {
      const newStats = { 
        ...prev.usageStats, 
        [actionId]: (prev.usageStats[actionId] || 0) + 1 
      };
      savePreferences({ usageStats: newStats });
      return { ...prev, usageStats: newStats };
    });
  }, []);

  // Get most used actions
  const getTopActions = useMemo(() => {
    return Object.entries(preferences.usageStats)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 3)
      .map(([id]) => id);
  }, [preferences.usageStats]);

  // Check if we should show behavior tip
  const shouldShowBehaviorTip = useMemo(() => {
    return getTopActions.length >= 2 && preferences.usageStats[getTopActions[0]]! > 3;
  }, [getTopActions, preferences.usageStats]);

  return {
    preferences,
    position: preferences.position,
    updatePosition,
    toggleVisibility,
    toggleExpanded,
    trackActionUsage,
    topActions: getTopActions,
    shouldShowBehaviorTip,
  };
}

