export default function TransparencyPage() {
  const navigate = useNavigate();
  const [activeFilter, setActiveFilter] = useState<'all' | 'سنوي' | 'ربعي'>('all');
  const [searchQuery, setSearchQuery] = useState('');

  useSEO({
    title: 'الشفافية - رحماء بينهم',
    description: 'الشفافية والحوكمة في مؤسسة رحماء بينهم - التقارير المالية والإدارية',
  });

  const filteredReports = REPORTS.filter((report) => {
    const matchesType = activeFilter === 'all' || report.type === activeFilter;
    const matchesSearch = report.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesType && matchesSearch;
  });

  return (
    <div className="min-h-screen pt-20" dir="rtl">
      {/* Hero Section */}
      <section className="relative py-20 overflow-hidden bg-gradient-to-b from-[var(--brand-green)]/10 to-white">
        <div className="absolute inset-0 overflow-hidden">
          <div className="absolute -top-40 -right-40 w-[500px] h-[500px] bg-[var(--brand-green)]/5 rounded-full blur-3xl" />
          <div className="absolute -bottom-40 -left-40 w-[500px] h-[500px] bg-[var(--brand-gold)]/5 rounded-full blur-3xl" />
        </div>
        
        <div className="container mx-auto px-4 relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center max-w-4xl mx-auto"
          >
            <div className="inline-flex items-center gap-2 bg-white/80 backdrop-blur-sm border border-[var(--brand-green)]/20 px-5 py-2 rounded-full mb-6 shadow-lg">
              <Shield className="w-4 h-4 text-[var(--brand-green)]" />
              <span className="text-[var(--brand-green)] text-sm font-medium">الشفافية والنزاهة</span>
            </div>
            
            <h1 className="text-5xl md:text-6xl font-bold mb-6">
              <span className="text-[var(--foreground)]">الشفافية </span>
              <span className="text-[var(--brand-green)]">ركن أساسي</span>
            </h1>
            
            <p className="text-xl text-[var(--muted-foreground)] max-w-3xl mx-auto leading-relaxed mb-8">
              نؤمن في مؤسسة رحماء بينهم بأن الشفافية هي أساس الثقة. 
              نلتزم بأعلى معايير الإفصاح والحوكمة لضمان وصول تبرعاتكم إلى مستحقيها.
            </p>

            {/* Quick Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {FINANCIAL_STATS.map((stat, i) => (
                <motion.div
                  key={stat.label}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2 + i * 0.1 }}
                  className="bg-white backdrop-blur-sm rounded-2xl p-5 border border-[var(--border)] shadow-lg"
                >
                  <div className="text-2xl font-bold text-[var(--foreground)]">{stat.value}</div>
                  <div className="text-sm text-[var(--muted-foreground)] mt-1">{stat.label}</div>
                  <div className={`text-xs font-semibold mt-1 ${stat.positive ? 'text-green-600' : 'text-amber-600'}`}>
                    {stat.change}
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        </div>
      </section>

      {/* Pillars Section */}
      <section className="py-20 bg-white">
        <div className="container mx-auto px-4">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-4xl md:text-5xl font-bold mb-4">
              <span className="text-[var(--brand-green)]">ركائز</span> الشفافية
            </h2>
            <p className="text-[var(--muted-foreground)] max-w-2xl mx-auto">
              أربع ركائز أساسية نبني عليها التزامنا بالشفافية
            </p>
          </motion.div>

          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6 max-w-6xl mx-auto">
            {TRANSPARENCY_PILLARS.map((pillar, i) => (
              <motion.div
                key={pillar.title}
                initial={{ opacity: 0, y: 30 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.1 }}
                className="group bg-white rounded-2xl p-8 border border-[var(--border)] shadow-lg hover:shadow-2xl transition-all duration-500 hover:-translate-y-2"
              >
                <div className="w-16 h-16 rounded-2xl bg-[var(--brand-green-pale)] flex items-center justify-center mb-5 group-hover:scale-110 transition-transform duration-300">
                  <pillar.icon className="w-8 h-8 text-[var(--brand-green)]" />
                </div>
                <h3 className="text-xl font-bold text-[var(--foreground)] mb-3">{pillar.title}</h3>
                <p className="text-[var(--muted-foreground)] leading-relaxed">{pillar.desc}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Governance Section */}
      <section className="py-20 bg-[var(--secondary)]">
        <div className="container mx-auto px-4">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-4xl md:text-5xl font-bold mb-4">
              هيكل <span className="text-[var(--brand-green)]">الحوكمة</span>
            </h2>
            <p className="text-[var(--muted-foreground)] max-w-2xl mx-auto">
              مجالس ولجان تضمن أعلى معايير الحوكمة والرقابة
            </p>
          </motion.div>

          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6 max-w-6xl mx-auto">
            {GOVERNANCE_BODIES.map((body, i) => (
              <motion.div
                key={body.title}
                initial={{ opacity: 0, y: 30 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.1 }}
                className="bg-white rounded-2xl p-6 border border-[var(--border)] shadow-md hover:shadow-xl transition-all duration-300"
              >
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-bold text-[var(--foreground)]">{body.title}</h3>
                  <span className="text-xs font-semibold text-[var(--brand-green)] bg-[var(--brand-green-pale)] px-3 py-1 rounded-full">
                    {body.members}
                  </span>
                </div>
                <p className="text-sm text-[var(--muted-foreground)] leading-relaxed">{body.desc}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Reports Section */}
      <section className="py-20 bg-white">
        <div className="container mx-auto px-4">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-4xl md:text-5xl font-bold mb-4">
              <span className="text-[var(--brand-green)]">التقارير</span> والإفصاحات
            </h2>
            <p className="text-[var(--muted-foreground)] max-w-2xl mx-auto">
              جميع تقاريرنا المالية والإدارية متاحة للتحميل والاطلاع
            </p>
          </motion.div>

          {/* Filters */}
          <div className="max-w-4xl mx-auto mb-8">
            <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
              <div className="flex gap-2">
                {['all', 'سنوي', 'ربعي'].map((filter) => (
                  <button
                    key={filter}
                    onClick={() => setActiveFilter(filter as any)}
                    className={`px-5 py-2 rounded-full text-sm font-semibold transition-all ${
                      activeFilter === filter
                        ? 'bg-[var(--brand-green)] text-white'
                        : 'bg-gray-100 text-[var(--muted-foreground)] hover:bg-gray-200'
                    }`}
                  >
                    {filter === 'all' ? 'الكل' : filter}
                  </button>
                ))}
              </div>

              <div className="relative">
                <Search className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="بحث في التقارير..."
                  className="w-64 pr-10 pl-4 py-2 border border-[var(--border)] rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/30"
                />
              </div>
            </div>
          </div>

          {/* Reports Grid */}
          <div className="grid md:grid-cols-2 gap-6 max-w-4xl mx-auto">
            {filteredReports.map((report, i) => (
              <motion.div
                key={report.id}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.1 }}
                className="group bg-white rounded-2xl p-6 border border-[var(--border)] shadow-md hover:shadow-xl transition-all duration-300"
              >
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-xl bg-[var(--brand-green-pale)] flex items-center justify-center">
                      <FileText className="w-6 h-6 text-[var(--brand-green)]" />
                    </div>
                    <div>
                      <h3 className="font-bold text-[var(--foreground)]">{report.title}</h3>
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                        report.type === 'سنوي' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'
                      }`}>
                        {report.type}
                      </span>
                    </div>
                  </div>
                  <span className="text-xs text-[var(--muted-foreground)]">{report.year}</span>
                </div>

                <div className="space-y-2 mb-4">
                  {report.highlights.map((h, j) => (
                    <div key={j} className="flex items-start gap-2">
                      <CheckCircle className="w-4 h-4 text-[var(--brand-green)] mt-0.5 flex-shrink-0" />
                      <span className="text-sm text-[var(--muted-foreground)]">{h}</span>
                    </div>
                  ))}
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-[var(--border)]">
                  <div className="flex items-center gap-3 text-xs text-[var(--muted-foreground)]">
                    <span>{report.size}</span>
                    <span>•</span>
                    <span>{report.pages} صفحة</span>
                  </div>
                  <button className="flex items-center gap-1 text-sm font-semibold text-[var(--brand-green)] hover:text-[var(--brand-green-light)] transition-colors">
                    <Download className="w-4 h-4" />
                    تحميل
                  </button>
                </div>
              </motion.div>
            ))}
          </div>

          {filteredReports.length === 0 && (
            <div className="text-center py-12">
              <Search className="w-16 h-16 text-gray-300 mx-auto mb-4" />
              <p className="text-[var(--muted-foreground)]">لا توجد تقارير تطابق بحثك</p>
            </div>
          )}
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-20 bg-gradient-to-br from-[var(--brand-green)] to-[var(--brand-green-light)]">
        <div className="container mx-auto px-4 text-center">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="max-w-3xl mx-auto"
          >
            <h2 className="text-4xl font-bold text-white mb-4">لديك استفسار حول الشفافية؟</h2>
            <p className="text-white/80 text-lg mb-8">
              يمكنك التواصل معنا لأي استفسار حول تقاريرنا المالية أو الإدارية
            </p>
            <button
              onClick={() => navigate('/contact')}
              className="inline-flex items-center gap-2 px-8 py-4 bg-white text-[var(--brand-green)] rounded-xl font-bold text-lg hover:shadow-2xl transition-all"
            >
              تواصل معنا
              <ArrowLeft className="w-5 h-5" />
            </button>
          </motion.div>
        </div>
      </section>
    </div>
  );
}

// Volunteer Page - صفحة التطوع
import { motion } from "framer-motion";
import { Loader2, CheckCircle, AlertCircle, Users, Heart, HandHelping, Globe, Shield, Award, Target, BarChart3, TrendingUp } from "lucide-react";
import { useState, useEffect } from "react";

import { PageHeader } from "@/app/components/PageHeader";
import { StatsGrid } from "@/app/components/StatsGrid";
import { contentBridge } from "@/shared/services/content-bridge.service";
import { intakeService } from "@/shared/services/intake.service";
import { useSEO } from "@/utils/seoAdvanced";

// مجالات التطوع حسب الدليل التشغيلي
const VOLUNTEER_FIELDS = [
  { id: 'education', label: 'تعليمي', icon: '📚', description: 'تدريس وتحفيظ' },
  { id: 'health', label: 'صحي', icon: '🏥', description: 'دعم طبي وتمريض' },
  { id: 'relief', label: 'إغاثي', icon: '🚚', description: 'توزيع مواد إغاثية' },
  { id: 'media', label: 'إعلامي', icon: '📱', description: 'تصميم ومونتاج' },
  { id: 'admin', label: 'إداري', icon: '📊', description: 'إدارة وتنسيق' },
  { id: 'tech', label: 'تقني', icon: '💻', description: 'تطوير ودعم تقني' },
  { id: 'logistics', label: 'لوجستي', icon: '📦', description: 'تخزين وتوزيع' },
  { id: 'fundraising', label: 'تأمين موارد', icon: '💰', description: 'جمع تبرعات وشراكات' },
];

const VOLUNTEER_STATS = [
  { label: 'متطوع نشط', value: '200+', icon: Users, color: 'text-[var(--brand-green)]' },
  { label: 'ميدان', value: '8', icon: Globe, color: 'text-blue-600' },
  { label: 'ساعات تطوع', value: '10,000+', icon: Award, color: 'text-purple-600' },
  { label: 'مشروع مدعوم', value: '50+', icon: Target, color: 'text-[var(--brand-gold)]' },
];

export default function VolunteerPage() {
  const [submitted, setSubmitted] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [contentSource, setContentSource] = useState<'static' | 'sanity'>('static');
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    field: '',
    reason: '',
  });

  useSEO({
    title: 'تطوع معنا - رحماء بينهم',
    description: 'انضم إلى فريق متطوعي رحماء بينهم - فرص تطوع في مجالات متعددة',
    keywords: ['تطوع', 'فرص تطوع', 'عمل خيري', 'رحماء بينهم'],
  });

  useEffect(() => {
    let cancelled = false;
    contentBridge.getContent<any>('impact')
      .then((result) => {
        if (!cancelled) {
          setContentSource(result.isDynamic ? 'sanity' : 'static');
        }
      })
      .catch(() => {
        if (!cancelled) setContentSource('static');
      });
    return () => { cancelled = true; };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSending(true);

    try {
      await intakeService.submitVolunteer({
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        field: formData.field,
        motivation: formData.reason,
      });
      setSubmitted(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'حدث خطأ أثناء إرسال الطلب');
    } finally {
      setSending(false);
    }
  };

  if (submitted) {
    return (
      <div className="min-h-screen bg-[var(--background)] pt-20" dir="rtl">
        <div className="container mx-auto px-4 py-20 text-center">
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-3xl p-12 border border-[var(--border)] max-w-2xl mx-auto shadow-xl"
          >
            <div className="w-24 h-24 mx-auto mb-6 bg-[var(--brand-green-pale)] rounded-full flex items-center justify-center">
              <CheckCircle className="w-12 h-12 text-[var(--brand-green)]" />
            </div>
            <h2 className="text-4xl font-bold text-[var(--foreground)] mb-4">
              تم استلام طلبك بنجاح!
            </h2>
            <p className="text-[var(--muted-foreground)] text-lg mb-6">
              شكراً لرغبتك في التطوع معنا. سنقوم بمراجعة طلبك والرد عليك قريباً.
            </p>
            <div className="bg-[var(--brand-green-pale)] rounded-xl p-6 mb-8">
              <div className="flex items-center justify-center gap-3 mb-3">
                <Shield className="w-5 h-5 text-[var(--brand-green)]" />
                <span className="font-bold text-[var(--brand-green)]">🔒 آمن وموثوق</span>
              </div>
              <p className="text-sm text-[var(--muted-foreground)]">
                سيظهر طلبك للمراجعة. سنتواصل معك قريباً عبر البريد الإلكتروني.
              </p>
            </div>
            <button
              onClick={() => setSubmitted(false)}
              className="px-8 py-3 bg-[var(--brand-green)] text-white rounded-xl font-bold hover:bg-[var(--brand-green-light)] transition-colors shadow-lg"
            >
              تقديم طلب آخر
            </button>
          </motion.div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[var(--background)]" dir="rtl">
      {/* Unified Page Header */}
      <PageHeader
        icon={HandHelping}
        badge="التطوع"
        title="تطوع مع رحماء بينهم"
        subtitle="انضم إلى فريق متطوعينا وكن جزءاً من التغيير الإيجابي في المجتمع"
      >
        <StatsGrid
          stats={[
            { label: 'متطوع نشط', value: '200+', icon: Users, color: 'green' },
            { label: 'ميدان', value: '8', icon: Globe, color: 'blue' },
            { label: 'ساعات تطوع', value: '10,000+', icon: Award, color: 'purple' },
            { label: 'مشروع مدعوم', value: '50+', icon: Target, color: 'gold' },
          ]}
          columns={4}
          variant="glass"
        />
      </PageHeader>

      {/* Volunteer Fields */}
      <section className="py-16 bg-white">
        <div className="container mx-auto px-4">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <span className="inline-flex items-center gap-2 text-[var(--brand-green)] text-sm font-semibold bg-[var(--brand-green-pale)] px-4 py-1.5 rounded-full mb-4">
              <Target className="w-4 h-4" />
              مجالات التطوع
            </span>
            <h2 className="text-3xl font-bold text-[var(--foreground)] mb-4">
              اختر مجال التطوع المناسب لك
            </h2>
            <p className="text-[var(--muted-foreground)] max-w-2xl mx-auto">
              نوفر فرص تطوع متنوعة تناسب مهاراتك واهتماماتك
            </p>
          </motion.div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 max-w-5xl mx-auto">
            {VOLUNTEER_FIELDS.map((field, i) => (
              <motion.div
                key={field.id}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.08 }}
                className="bg-white rounded-2xl p-6 border border-[var(--border)] shadow-lg text-center hover:shadow-xl transition-all duration-300 hover:-translate-y-1"
              >
                <div className="text-4xl mb-3">{field.icon}</div>
                <h3 className="font-bold text-[var(--foreground)] mb-1">{field.label}</h3>
                <p className="text-xs text-[var(--muted-foreground)]">{field.description}</p>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Application Form */}
      <section className="py-12 bg-[var(--secondary)]">
        <div className="container mx-auto px-4">
          <div className="max-w-3xl mx-auto">
            <motion.div
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="bg-white rounded-3xl p-8 md:p-12 border border-[var(--border)] shadow-lg"
            >
              {error && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="mb-6 p-4 bg-red-50 text-red-700 rounded-xl border border-red-200"
                >
                  {error}
                </motion.div>
              )}

              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="name" className="block text-sm font-semibold text-[var(--foreground)] mb-2">
                      الاسم الكامل *
                    </label>
                    <input
                      id="name"
                      name="name"
                      type="text"
                      required
                      value={formData.name}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border border-[var(--border)] focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                      placeholder="أدخل اسمك"
                    />
                  </div>
                  <div>
                    <label htmlFor="email" className="block text-sm font-semibold text-[var(--foreground)] mb-2">
                      البريد الإلكتروني *
                    </label>
                    <input
                      id="email"
                      name="email"
                      type="email"
                      required
                      value={formData.email}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border border-[var(--border)] focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                      placeholder="example@email.com"
                    />
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="phone" className="block text-sm font-semibold text-[var(--foreground)] mb-2">
                      رقم الهاتف *
                    </label>
                    <input
                      id="phone"
                      name="phone"
                      type="tel"
                      required
                      value={formData.phone}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border border-[var(--border)] focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                      placeholder="+967 ..."
                    />
                  </div>
                  <div>
                    <label htmlFor="field" className="block text-sm font-semibold text-[var(--foreground)] mb-2">
                      مجال التطوع المفضل
                    </label>
                    <select
                      id="field"
                      name="field"
                      value={formData.field}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border border-[var(--border)] focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                    >
                      <option value="">اختر المجال</option>
                      {VOLUNTEER_FIELDS.map((field) => (
                        <option key={field.id} value={field.id}>
                          {field.label}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div>
                  <label htmlFor="reason" className="block text-sm font-semibold text-[var(--foreground)] mb-2">
                    لماذا ترغب في التطوع معنا؟ *
                  </label>
                  <textarea
                    id="reason"
                    name="reason"
                    rows={4}
                    required
                    value={formData.reason}
                    onChange={handleChange}
                    className="w-full px-4 py-3 rounded-xl border border-[var(--border)] focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all resize-none"
                    placeholder="اكتب دوافعك للتطوع مع رحماء بينهم..."
                  />
                </div>

                <button
                  type="submit"
                  disabled={sending}
                  className="w-full bg-[var(--brand-green)] text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-[var(--brand-green-light)] transition-colors shadow-lg hover:shadow-xl disabled:opacity-50"
                >
                  {sending ? (
                    <Loader2 className="w-5 h-5 animate-spin" />
                  ) : (
                    <>
                      <HandHelping className="w-5 h-5" />
                      تقديم طلب التطوع
                    </>
                  )}
                </button>

                <div className="mt-4 text-center text-sm text-[var(--muted-foreground)]">
                  <div className="flex items-center justify-center gap-2">
                    <Shield className="w-4 h-4 text-[var(--brand-green)]" />
                    <span>🔒 بياناتك محمية وآمنة</span>
                  </div>
                </div>
              </form>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Content Source Indicator (dev only) */}
      {import.meta.env?.DEV && (
        <div className="fixed bottom-4 left-4 z-50 bg-purple-600 text-white text-xs px-3 py-2 rounded-lg shadow-lg">
          <div className="flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full ${contentSource === 'sanity' ? 'bg-green-400' : 'bg-yellow-400'}`} />
            <span>{contentSource === 'sanity' ? 'Sanity CMS' : 'Static Content'}</span>
          </div>
        </div>
      )}
    </div>
  );
}

// Zakat Calculator Page - حاسبة الزكاة الشرعية
import { motion } from "framer-motion";
import { Calculator, DollarSign, Gem, Calendar, Bell, CheckCircle, ArrowLeft, ArrowRight, Shield, Heart, TrendingUp } from 'lucide-react';
import { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';

import { analyticsService } from '@/shared/services/analytics.service';
import { contentBridge } from '@/shared/services/content-bridge.service';
import { useSEO } from '@/utils/seoAdvanced';

type ZakatType = 'money' | 'gold' | 'fitr';

const GOLD_PRICE_PER_GRAM = 30; // ريال عماني تقريبي

export default function ZakatPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<ZakatType>('money');
  const [cashAmount, setCashAmount] = useState(0);
  const [goldWeight, setGoldWeight] = useState(0);
  const [familyMembers, setFamilyMembers] = useState(1);
  const [zakatResult, setZakatResult] = useState<number | null>(null);
  const [reminderEmail, setReminderEmail] = useState('');
  const [reminderSaved, setReminderSaved] = useState(false);
  const [contentSource, setContentSource] = useState<'static' | 'sanity'>('static');

  useSEO({
    title: 'حاسبة الزكاة - رحماء بينهم',
    description: 'احسب زكاة مالك وذهبك وفطرك بدقة وسهولة، وأدِ زكاتك في مصارفها الشرعية',
    keywords: ['زكاة', 'حاسبة زكاة', 'زكاة المال', 'زكاة الذهب', 'زكاة الفطر', 'رحماء بينهم'],
  });

  useEffect(() => {
    let cancelled = false;
    contentBridge.getContent<any>('impact')
      .then((result) => {
        if (!cancelled) {
          setContentSource(result.isDynamic ? 'sanity' : 'static');
        }
      })
      .catch(() => {
        if (!cancelled) setContentSource('static');
      });
    return () => { cancelled = true; };
  }, []);

  const NISAB = useMemo(() => ({
    money: 85 * GOLD_PRICE_PER_GRAM, // ما يعادل 85 جرام ذهب
    gold: 85,
    fitr: 2.5, // كيلو جرام قمح تقريباً
  }), []);

  const calculateMoneyZakat = () => {
    if (cashAmount >= NISAB.money) {
      return cashAmount * 0.025;
    }
    return 0;
  };

  const calculateGoldZakat = () => {
    if (goldWeight >= NISAB.gold) {
      return goldWeight * GOLD_PRICE_PER_GRAM * 0.025;
    }
    return 0;
  };

  const calculateFitrZakat = () => {
    return familyMembers * NISAB.fitr;
  };

  const handleCalculate = () => {
    let result = 0;
    switch (activeTab) {
      case 'money':
        result = calculateMoneyZakat();
        break;
      case 'gold':
        result = calculateGoldZakat();
        break;
      case 'fitr':
        result = calculateFitrZakat();
        break;
    }
    setZakatResult(result);
    try { analyticsService.generateImpactReport(); } catch { /* non-critical */ }
  };

  const handleReminderSave = () => {
    if (reminderEmail) {
      setReminderSaved(true);
      setTimeout(() => setReminderSaved(false), 3000);
    }
  };

  const handleDonateZakat = () => {
    navigate('/donate', { state: { zakatAmount: zakatResult } });
  };

  return (
    <div className="min-h-screen bg-[var(--background)] pt-20" dir="rtl">
      {/* Hero Section */}
      <section className="relative py-20 bg-gradient-to-b from-[var(--brand-green)]/10 to-white overflow-hidden">
        <div className="absolute inset-0 overflow-hidden">
          <div className="absolute -top-40 -right-40 w-[600px] h-[600px] bg-[var(--brand-green)]/5 rounded-full blur-3xl" />
          <div className="absolute -bottom-40 -left-40 w-[500px] h-[500px] bg-[var(--brand-gold)]/5 rounded-full blur-3xl" />
        </div>

        <div className="container mx-auto px-4 relative z-10">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center max-w-4xl mx-auto"
          >
            <div className="inline-flex items-center gap-2 bg-white/80 backdrop-blur-sm border border-[var(--brand-green)]/20 px-5 py-2 rounded-full mb-6 shadow-lg">
              <Calculator className="w-4 h-4 text-[var(--brand-green)]" />
              <span className="text-[var(--brand-green)] text-sm font-medium">حاسبة الزكاة الشرعية</span>
            </div>

            <h1 className="text-5xl md:text-6xl font-bold text-[var(--foreground)] mb-4">
              احسب <span className="text-[var(--brand-green)]">زكاتك</span> بسهولة
            </h1>
            <p className="text-xl text-[var(--muted-foreground)] max-w-2xl mx-auto mb-8">
              أداة شرعية موثوقة لحساب زكاة المال والذهب والفطر، مع توجيه لإخراجها في مصارفها
            </p>

            {/* Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 max-w-3xl mx-auto">
              <div className="bg-white/80 backdrop-blur-sm rounded-xl p-4 border border-[var(--border)]">
                <div className="text-[var(--brand-green)] flex justify-center mb-1">
                  <DollarSign className="w-6 h-6" />
                </div>
                <div className="text-2xl font-bold text-[var(--foreground)]">2.5%</div>
                <div className="text-xs text-[var(--muted-foreground)]">نسبة الزكاة</div>
              </div>
              <div className="bg-white/80 backdrop-blur-sm rounded-xl p-4 border border-[var(--border)]">
                <div className="text-[var(--brand-gold)] flex justify-center mb-1">
                  <Gem className="w-6 h-6" />
                </div>
                <div className="text-2xl font-bold text-[var(--foreground)]">{NISAB.gold} جرام</div>
                <div className="text-xs text-[var(--muted-foreground)]">نصاب الذهب</div>
              </div>
              <div className="bg-white/80 backdrop-blur-sm rounded-xl p-4 border border-[var(--border)]">
                <div className="text-blue-600 flex justify-center mb-1">
                  <Calculator className="w-6 h-6" />
                </div>
                <div className="text-2xl font-bold text-[var(--foreground)]">{NISAB.money.toLocaleString('ar-SA')} ر.ي</div>
                <div className="text-xs text-[var(--muted-foreground)]">نصاب المال</div>
              </div>
              <div className="bg-white/80 backdrop-blur-sm rounded-xl p-4 border border-[var(--border)]">
                <div className="text-purple-600 flex justify-center mb-1">
                  <Heart className="w-6 h-6" />
                </div>
                <div className="text-2xl font-bold text-[var(--foreground)]">8</div>
                <div className="text-xs text-[var(--muted-foreground)]">مصارف الزكاة</div>
              </div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* Main Calculator */}
      <section className="py-12">
        <div className="container mx-auto px-4">
          <div className="max-w-3xl mx-auto">
            {/* Zakat Type Tabs */}
            <div className="flex gap-2 mb-8">
              {[
                { id: 'money', label: 'زكاة المال', icon: DollarSign },
                { id: 'gold', label: 'زكاة الذهب', icon: Gem },
                { id: 'fitr', label: 'زكاة الفطر', icon: Calendar },
              ].map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => { setActiveTab(tab.id as ZakatType); setZakatResult(null); }}
                  className={`flex-1 p-4 rounded-xl border-2 transition-all flex flex-col items-center gap-2 ${
                    activeTab === tab.id
                      ? 'border-[var(--brand-green)] bg-[var(--brand-green-pale)] text-[var(--brand-green)]'
                      : 'border-[var(--border)] hover:border-[var(--brand-green)]'
                  }`}
                >
                  <tab.icon className="w-8 h-8" />
                  <span className="font-semibold">{tab.label}</span>
                </button>
              ))}
            </div>

            {/* Money Zakat */}
            {activeTab === 'money' && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white rounded-3xl p-8 border border-[var(--border)] shadow-lg"
              >
                <h2 className="text-2xl font-bold text-[var(--foreground)] mb-6">حساب زكاة المال</h2>

                <div className="mb-6">
                  <label htmlFor="cashAmount" className="block text-lg font-semibold text-[var(--foreground)] mb-2">
                    إجمالي المبلغ المملوك (ر.ي)
                  </label>
                  <div className="relative">
                    <input
                      id="cashAmount"
                      type="number"
                      value={cashAmount || ''}
                      onChange={(e) => setCashAmount(Number(e.target.value))}
                      className="w-full p-4 pr-12 border-2 border-[var(--border)] rounded-xl text-lg focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                      placeholder="أدخل المبلغ"
                    />
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--muted-foreground)]">ر.ي</span>
                  </div>
                </div>

                <div className="bg-[var(--brand-green-pale)] p-4 rounded-xl mb-6">
                  <p className="text-sm text-[var(--muted-foreground)]">
                    نصاب الزكاة: {NISAB.money.toLocaleString('ar-SA')} ر.ي (ما يعادل 85 جرام ذهب)
                  </p>
                </div>

                <div className="space-y-3 mb-8">
                  <label className="flex items-center gap-3 p-3 border border-[var(--border)] rounded-xl cursor-pointer hover:border-[var(--brand-green)] transition-colors">
                    <input type="checkbox" className="w-4 h-4 text-[var(--brand-green)]" defaultChecked />
                    <span className="text-[var(--foreground)]">بلغ المال النصاب الشرعي</span>
                  </label>
                  <label className="flex items-center gap-3 p-3 border border-[var(--border)] rounded-xl cursor-pointer hover:border-[var(--brand-green)] transition-colors">
                    <input type="checkbox" className="w-4 h-4 text-[var(--brand-green)]" defaultChecked />
                    <span className="text-[var(--foreground)]">مر عليه عام هجري كامل</span>
                  </label>
                </div>

                <button onClick={handleCalculate} className="w-full bg-[var(--brand-green)] text-white py-4 rounded-xl font-bold text-lg hover:bg-[var(--brand-green-light)] transition-colors shadow-lg hover:shadow-xl">
                  احسب الزكاة
                </button>
              </motion.div>
            )}

            {/* Gold Zakat */}
            {activeTab === 'gold' && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white rounded-3xl p-8 border border-[var(--border)] shadow-lg"
              >
                <h2 className="text-2xl font-bold text-[var(--foreground)] mb-6">حساب زكاة الذهب</h2>

                <div className="mb-6">
                  <label htmlFor="goldWeight" className="block text-lg font-semibold text-[var(--foreground)] mb-2">
                    وزن الذهب المملوك (جرام)
                  </label>
                  <input
                    id="goldWeight"
                    type="number"
                    value={goldWeight || ''}
                    onChange={(e) => setGoldWeight(Number(e.target.value))}
                    className="w-full p-4 border-2 border-[var(--border)] rounded-xl text-lg focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                    placeholder="أدخل الوزن بالجرام"
                  />
                </div>

                <div className="bg-[var(--brand-green-pale)] p-4 rounded-xl mb-6">
                  <p className="text-sm text-[var(--muted-foreground)]">
                    نصاب الذهب: {NISAB.gold} جرام (سعر الجرام ~ {GOLD_PRICE_PER_GRAM} ر.ي)
                  </p>
                </div>

                <button onClick={handleCalculate} className="w-full bg-[var(--brand-green)] text-white py-4 rounded-xl font-bold text-lg hover:bg-[var(--brand-green-light)] transition-colors shadow-lg hover:shadow-xl">
                  احسب الزكاة
                </button>
              </motion.div>
            )}

            {/* Fitr Zakat */}
            {activeTab === 'fitr' && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white rounded-3xl p-8 border border-[var(--border)] shadow-lg"
              >
                <h2 className="text-2xl font-bold text-[var(--foreground)] mb-6">زكاة الفطر</h2>
                <div className="bg-gradient-to-r from-[var(--brand-green)]/10 to-[var(--brand-green)]/5 p-6 rounded-xl mb-6">
                  <p className="text-lg text-[var(--foreground)]">
                    <strong>مقدار زكاة الفطر:</strong> {NISAB.fitr} ر.ي للشخص الواحد
                  </p>
                  <p className="text-sm text-[var(--muted-foreground)] mt-2">
                    تُقدر بقيمة 2.5 كيلو جرام من القمح أو ما يعادله من الأرز/التمر
                  </p>
                </div>

                <div className="mb-6">
                  <label htmlFor="familyMembers" className="block text-lg font-semibold text-[var(--foreground)] mb-2">
                    عدد أفراد الأسرة
                  </label>
                  <input
                    id="familyMembers"
                    type="number"
                    value={familyMembers || ''}
                    onChange={(e) => setFamilyMembers(Number(e.target.value))}
                    className="w-full p-4 border-2 border-[var(--border)] rounded-xl text-lg focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                    placeholder="أدخل العدد"
                    min="1"
                  />
                </div>

                <button onClick={handleCalculate} className="w-full bg-[var(--brand-green)] text-white py-4 rounded-xl font-bold text-lg hover:bg-[var(--brand-green-light)] transition-colors shadow-lg hover:shadow-xl">
                  احسب الإجمالي
                </button>
              </motion.div>
            )}

            {/* Zakat Result */}
            {zakatResult !== null && zakatResult > 0 && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white rounded-3xl p-8 mt-6 border-2 border-[var(--brand-green)] shadow-lg"
              >
                <div className="text-center mb-6">
                  <CheckCircle className="w-16 h-16 mx-auto mb-4 text-[var(--brand-green)]" />
                  <h3 className="text-2xl font-bold text-[var(--foreground)] mb-2">قيمة الزكاة المستحقة</h3>
                  <div className="text-5xl font-bold text-[var(--brand-green)] mb-2">
                    {zakatResult.toFixed(2)}
                  </div>
                  <p className="text-[var(--muted-foreground)]">ريال عماني</p>
                </div>

                <div className="bg-[var(--brand-green-pale)] p-6 rounded-xl mb-6">
                  <div className="flex items-start gap-3 mb-3">
                    <TrendingUp className="w-5 h-5 text-[var(--brand-green)] flex-shrink-0 mt-0.5" />
                    <div>
                      <h4 className="font-bold text-[var(--brand-green)] mb-1">أثر زكاتك</h4>
                      <p className="text-sm text-[var(--muted-foreground)]">
                        بهذا المبلغ يمكنك إطعام {Math.floor(zakatResult / 2)} شخص لمدة يوم، أو دعم أسرة متكاملة لأسبوع كامل
                      </p>
                    </div>
                  </div>
                </div>

                <button
                  onClick={handleDonateZakat}
                  className="w-full bg-[var(--brand-green)] text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-[var(--brand-green-light)] transition-colors shadow-lg hover:shadow-xl"
                >
                  <Heart className="w-5 h-5" fill="white" />
                  أخرج زكاتك الآن
                  <ArrowLeft className="w-5 h-5" />
                </button>
              </motion.div>
            )}

            {zakatResult === 0 && zakatResult !== null && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white rounded-3xl p-8 mt-6 border border-[var(--border)] shadow-lg"
              >
                <div className="text-center">
                  <div className="w-16 h-16 mx-auto mb-4 bg-[var(--brand-gold-pale)] rounded-full flex items-center justify-center">
                    <Calculator className="w-8 h-8 text-[var(--brand-gold)]" />
                  </div>
                  <h3 className="text-xl font-bold text-[var(--foreground)] mb-2">لم يبلغ النصاب الشرعي</h3>
                  <p className="text-[var(--muted-foreground)]">
                    المبلغ المملوك لم يبلغ النصاب الشرعي، لا تجب عليك الزكاة.
                  </p>
                </div>
              </motion.div>
            )}

            {/* Reminder Tool */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="bg-white rounded-3xl p-8 mt-6 border border-[var(--border)] shadow-lg"
            >
              <h3 className="text-xl font-bold text-[var(--foreground)] mb-4 flex items-center gap-2">
                <Bell className="w-6 h-6 text-[var(--brand-green)]" />
                تذكير بموعد الزكاة
              </h3>
              <p className="text-[var(--muted-foreground)] mb-4">
                أدخل بريدك الإلكتروني ليتم تذكيرك في نفس التاريخ الهجري من العام القادم
              </p>
              <div className="flex gap-3">
                <input
                  type="email"
                  value={reminderEmail}
                  onChange={(e) => setReminderEmail(e.target.value)}
                  className="flex-1 p-4 border-2 border-[var(--border)] rounded-xl focus:ring-2 focus:ring-[var(--brand-green)]/30 outline-none transition-all"
                  placeholder="البريد الإلكتروني"
                />
                <button
                  onClick={handleReminderSave}
                  className="bg-[var(--brand-green)] text-white px-6 py-4 rounded-xl font-bold hover:bg-[var(--brand-green-light)] transition-colors shadow-lg"
                >
                  {reminderSaved ? 'تم الحفظ ✅' : 'تذكير'}
                </button>
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* Content Source Indicator (dev only) */}
      {import.meta.env?.DEV && (
        <div className="fixed bottom-4 left-4 z-50 bg-purple-600 text-white text-xs px-3 py-2 rounded-lg shadow-lg">
          <div className="flex items-center gap-2">
            <div className={`w-2 h-2 rounded-full ${contentSource === 'sanity' ? 'bg-green-400' : 'bg-yellow-400'}`} />
            <span>{contentSource === 'sanity' ? 'Sanity CMS' : 'Static Content'}</span>
          </div>
        </div>
      )}
    </div>
  );
}

// ErrorBoundary - مكون لالتقاط الأخطاء وعرض رسائل بديلة
import { Component, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: any) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback || (
        <div className="min-h-screen flex items-center justify-center bg-[var(--secondary)]" dir="rtl">
          <div className="text-center p-8">
            <div className="text-6xl mb-4">⚠️</div>
            <h2 className="text-2xl font-bold text-[var(--foreground)] mb-2">
