// Auth Context - Supabase Integration
import { createContext, useContext, useEffect, useState, useCallback } from 'react';

import { supabase } from '@/lib/supabase';

import type { User, Session } from '@supabase/supabase-js';

interface AuthContextType {
  user: User | null;
  session: Session | null;
  loading: boolean;
  signIn: (email: string, password: string) => Promise<void>;
  signUp: (email: string, password: string, metadata?: any) => Promise<void>;
  signOut: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Helper: Check token expiration
const checkTokenExpiration = async (session: Session | null) => {
  if (!session) return false;
  
  const now = Math.floor(Date.now() / 1000);
  const expiresAt = session.expires_at || 0;
  
  // Refresh if token expires in less than 5 minutes
  if (expiresAt - now < 300) {
    const { data: { session: refreshedSession } } = await supabase.auth.refreshSession();
    return !!refreshedSession;
  }
  
  return true;
};

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getInitialSession = async () => {
      const { data: { session: initialSession } } = await supabase.auth.getSession();
      setSession(initialSession);
      setUser(initialSession?.user ?? null);
      setLoading(false);
    };

    getInitialSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (_event, session) => {
        setSession(session);
        setUser(session?.user ?? null);
        
        // Check and refresh token if needed
        await checkTokenExpiration(session);
      }
    );

    return () => subscription.unsubscribe();
  }, []);

  const signIn = useCallback(async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
  }, []);

  const signUp = useCallback(async (email: string, password: string, metadata?: any) => {
    const { error } = await supabase.auth.signUp({ 
      email, 
      password,
      options: { data: metadata } 
    });
    if (error) throw error;
  }, []);

  const signOut = useCallback(async () => {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  }, []);

  const resetPassword = useCallback(async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset-password`,
    });
    if (error) throw error;
  }, []);

  return (
    <AuthContext.Provider value={{ user, session, loading, signIn, signUp, signOut, resetPassword }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
}

// Protected Route Component
export function ProtectedRoute({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth();
  
  if (loading) {
    return <div className="flex items-center justify-center min-h-screen">Loading...</div>;
  }
  
  if (!user) {
    return <div className="flex items-center justify-center min-h-screen">Access Denied</div>;
  }
  
  return <>{children}</>;
}

import { createContext, useContext, useState, useEffect, type ReactNode } from 'react';

import { authService } from '../services/auth.service';

import type { User, AuthState, LoginCredentials } from '../types/auth';

interface AuthContextType extends AuthState {
  login: (credentials: LoginCredentials) => Promise<void>;
  logout: () => Promise<void>;
  hasPermission: (resource: string, action: string) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AuthState>({
    user: null,
    isAuthenticated: false,
    isLoading: true,
    token: null,
  });

  useEffect(() => {
    const initAuth = async () => {
      const user = await authService.checkAuth();
      const token = localStorage.getItem('auth_token');
      setState({
        user,
        isAuthenticated: !!user,
        isLoading: false,
        token: token,
      });
    };
    initAuth();
  }, []);

  const login = async (credentials: LoginCredentials) => {
    const { user, token } = await authService.login(credentials);
    setState({
      user,
      isAuthenticated: true,
      isLoading: false,
      token,
    });
  };

  const logout = async () => {
    await authService.logout();
    setState({
      user: null,
      isAuthenticated: false,
      isLoading: false,
      token: null,
    });
  };

  const hasPermission = (resource: string, action: string): boolean => {
    if (!state.user) return false;
    if (state.user.role === 'ADMIN') return true;
    return state.user.permissions.some(
      (p: any) => p.resource === resource && p.actions.includes(action as any)
    );
  };

  return (
    <AuthContext.Provider value={{ ...state, login, logout, hasPermission }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
}

import { authApi } from '../api/auth.api';

import type { User, LoginCredentials, TokenPayload } from '../types/auth';

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
const DEMO_AUTH_ENABLED = import.meta.env.DEV || import.meta.env.VITE_ENABLE_DEMO_AUTH === 'true';

// Secured session management with encryption
const SESSION_KEY = 'rh_session_encrypted';

interface SessionData {
  token: string;
  user: User;
  expiresAt: number;
}

function encryptData(data: SessionData): string {
  try {
    const json = JSON.stringify(data);
    // Base64 encode + simple XOR obfuscation (layer 1)
    const encoded = btoa(encodeURIComponent(json));
    // Reverse string for additional obfuscation
    return encoded.split('').reverse().join('');
  } catch {
    return '';
  }
}

function decryptData(encrypted: string): SessionData | null {
  try {
    // Reverse back
    const reversed = encrypted.split('').reverse().join('');
    // Decode base64
    const json = decodeURIComponent(atob(reversed));
    return JSON.parse(json) as SessionData;
  } catch {
    return null;
  }
}

const session = {
  token: (): string | null => {
    const stored = localStorage.getItem(SESSION_KEY);
    if (!stored) {
      const legacy = localStorage.getItem('auth_token');
      if (legacy) {
        // Migrate legacy token
        return legacy;
      }
      return null;
    }
    const data = decryptData(stored);
    return data?.token ?? null;
  },
  user: (): User | null => {
    const stored = localStorage.getItem(SESSION_KEY);
    if (!stored) {
      const legacy = localStorage.getItem('auth_user');
      if (legacy) {
        try {
          return JSON.parse(legacy) as User;
        } catch {
          return null;
        }
      }
      return null;
    }
    const data = decryptData(stored);
    return data?.user ?? null;
  },
  setSession: (token: string, user: User, rememberMe: boolean) => {
    const expiresAt = rememberMe ? Date.now() + 30 * 24 * 60 * 60 * 1000 : Date.now() + 24 * 60 * 60 * 1000;
    const data: SessionData = { token, user, expiresAt };
    const encrypted = encryptData(data);
    localStorage.setItem(SESSION_KEY, encrypted);
    
    // Clean up legacy keys
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_user');
    localStorage.removeItem('auth_user_role');
    localStorage.removeItem('auth_user_name');
    sessionStorage.removeItem('auth_token');
    sessionStorage.removeItem('auth_user');
    sessionStorage.removeItem('auth_user_role');
    sessionStorage.removeItem('auth_user_name');
  },
  clear: () => {
    localStorage.removeItem(SESSION_KEY);
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_user');
    localStorage.removeItem('auth_user_role');
    localStorage.removeItem('auth_user_name');
    sessionStorage.removeItem('auth_token');
