    const adminPassword = import.meta.env.VITE_ADMIN_PASSWORD;
    
    if (sanitizedEmail === adminEmail.toLowerCase()) {
      // If admin password is set in env, use it; otherwise use a secure generated default
      const validPassword = adminPassword 
        ? credentials.password === adminPassword 
        : false;
      
      if (!validPassword) {
        throw new Error('البريد الإلكتروني أو كلمة المرور غير صحيحة');
      }

      const user = ENV_USERS[0];
      const token = generateSecureToken(user);
      
      session.setSession(token, user, credentials.rememberMe ?? false);
      return { user, token };
    }

    throw new Error('البريد الإلكتروني أو كلمة المرور غير صحيحة');
  },

  async logout(): Promise<void> {
    try {
      await authApi.logout();
    } catch {
      // Silently fail API logout
    }
    session.clear();
    
    // Clear rate limiting for this session
    for (const [key] of loginAttempts) {
      loginAttempts.delete(key);
    }
  },

  async checkAuth(): Promise<User | null> {
    const token = session.token();
    const user = session.user();
    
    if (!token || !user) return null;
    
    if (isTokenExpired(token)) {
      // Try to refresh token
      try {
        const newToken = await this.refreshToken();
        if (!newToken) {
          await this.logout();
          return null;
        }
      } catch {
        await this.logout();
        return null;
      }
    }
    
    return user;
  },

  async refreshToken(): Promise<string | null> {
    const token = session.token();
    if (!token) return null;
    
    try {
      const newToken = await authApi.refreshToken();
      const user = session.user();
      if (user) {
        session.setSession(newToken, user, true);
      }
      return newToken;
    } catch {
      // If refresh fails, extend current session
      const user = session.user();
      if (user) {
        const newToken = generateSecureToken(user);
        session.setSession(newToken, user, true);
        return newToken;
      }
      return null;
    }
  },

  async getAllUsers(): Promise<User[]> {
    // Try to get from API/Supabase first, fallback to env users
    try {
      const response = await fetch('/api/users', {
        headers: { 'Authorization': `Bearer ${session.token()}` },
      });
      if (response.ok) {
        return await response.json();
      }
    } catch {
      // Fallback to local
    }
    return ENV_USERS;
  },

  async getUserById(id: string): Promise<User | undefined> {
    return ENV_USERS.find(u => u.id === id);
  },

  async updateUser(id: string, updates: Partial<User>): Promise<User | null> {
    try {
      const response = await fetch(`/api/users/${id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${session.token()}`,
        },
        body: JSON.stringify(updates),
      });
      if (response.ok) {
        return await response.json();
      }
    } catch {
      // Fallback
    }
    return null;
  },

  async createUser(user: Omit<User, 'id'> & { id?: string }): Promise<User> {
    const newUser = { ...user, id: user.id || crypto.randomUUID?.() || `usr_${Date.now()}` } as User;
    
    try {
      const response = await fetch('/api/users', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${session.token()}`,
        },
        body: JSON.stringify(newUser),
      });
      if (response.ok) {
        return await response.json();
      }
    } catch {
      // Fallback
    }
    
    return newUser;
  },

  async deleteUser(id: string): Promise<boolean> {
    try {
      const response = await fetch(`/api/users/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${session.token()}` },
      });
      return response.ok;
    } catch {
      return false;
    }
  },

  getCurrentUser(): User | null {
    return session.user();
  },

  isAuthenticated(): boolean {
    const token = session.token();
    const user = session.user();
    return !!token && !!user && !isTokenExpired(token);
  },
};

// Enterprise Architecture Patterns - Advanced System Design

// ============================================================
// 1. Strategy Pattern
// ============================================================
interface Strategy<T> {
  execute(context: T): Promise<any>;
}

class StrategyContext<T> {
  private strategies: Map<string, Strategy<T>> = new Map();
  private currentStrategy?: string;

  registerStrategy(name: string, strategy: Strategy<T>) {
    this.strategies.set(name, strategy);
  }

  setStrategy(name: string) {
    if (this.strategies.has(name)) {
      this.currentStrategy = name;
    }
  }

  async execute(context: T): Promise<any> {
    if (!this.currentStrategy) {
      throw new Error('No strategy selected');
    }
    const strategy = this.strategies.get(this.currentStrategy);
    if (!strategy) {
      throw new Error(`Strategy ${this.currentStrategy} not found`);
    }
    return strategy.execute(context);
  }
}

// ============================================================
// 2. Observer Pattern (Event-Driven)
// ============================================================
interface Observer<T> {
  update(data: T): void | Promise<void>;
}

class Observable<T> {
  private observers: Set<Observer<T>> = new Set();

  subscribe(observer: Observer<T>): () => void {
    this.observers.add(observer);
    return () => this.observers.delete(observer);
  }

  async notify(data: T): Promise<void> {
    const promises = Array.from(this.observers).map(observer => 
      Promise.resolve(observer.update(data)).catch(err => 
        console.error('Observer error:', err)
      )
    );
    await Promise.all(promises);
  }
}

// ============================================================
// 3. Decorator Pattern
// ============================================================
interface Component {
  operation(): string;
}

class ConcreteComponent implements Component {
  operation(): string {
    return 'ConcreteComponent';
  }
}

abstract class ComponentDecorator implements Component {
  constructor(protected component: Component) {}

  operation(): string {
    return this.component.operation();
  }
}

class LoggingDecorator extends ComponentDecorator {
  operation(): string {
    const result = super.operation();
    console.log(`[LOG] ${result}`);
    return result;
  }
}

class CachingDecorator extends ComponentDecorator {
  private cache = new Map<string, string>();

  operation(): string {
    const key = this.component.constructor.name;
    if (this.cache.has(key)) {
      return this.cache.get(key)!;
    }
    const result = super.operation();
    this.cache.set(key, result);
    return result;
  }
}

