// 4. Factory Pattern
// ============================================================
interface Product {
  name: string;
  price: number;
}

class ProductA implements Product {
  name = 'Product A';
  price = 100;
}

class ProductB implements Product {
  name = 'Product B';
  price = 200;
}

class ProductFactory {
  static create(type: 'A' | 'B'): Product {
    switch (type) {
      case 'A':
        return new ProductA();
      case 'B':
        return new ProductB();
      default:
        throw new Error(`Unknown product type: ${type}`);
    }
  }
}

// ============================================================
// 5. Adapter Pattern
// ============================================================
interface Target {
  request(): string;
}

class Adaptee {
  specificRequest(): string {
    return 'Adaptee specific request';
  }
}

class Adapter implements Target {
  constructor(private adaptee: Adaptee) {}

  request(): string {
    return this.adaptee.specificRequest();
  }
}

// ============================================================
// 6. Proxy Pattern
// ============================================================
interface Service {
  request(): Promise<string>;
}

class RealService implements Service {
  async request(): Promise<string> {
    return 'Real service response';
  }
}

class ProxyService implements Service {
  constructor(private realService: Service, private cache: Map<string, string>) {}

  async request(): Promise<string> {
    const cacheKey = 'service_request';
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey)!;
    }

    const result = await this.realService.request();
    this.cache.set(cacheKey, result);
    return result;
  }
}

