// ============================================================
// 11. Dependency Injection Container
// ============================================================
interface ServiceDescriptor {
  token: any;
  implementation: new (...args: any[]) => any;
  singleton?: boolean;
  instance?: any;
}

class DIContainer {
  private static instance: DIContainer;
  private services: Map<string, ServiceDescriptor> = new Map();

  static getInstance(): DIContainer {
    if (!DIContainer.instance) {
      DIContainer.instance = new DIContainer();
    }
    return DIContainer.instance;
  }

  register(token: string, implementation: new (...args: any[]) => any, singleton = true) {
    this.services.set(token, {
      token,
      implementation,
      singleton,
      instance: singleton ? new implementation() : undefined,
    });
  }

  resolve<T>(token: string): T {
    const descriptor = this.services.get(token);
    if (!descriptor) {
      throw new Error(`Service ${token} not registered`);
    }

    if (descriptor.singleton && descriptor.instance) {
      return descriptor.instance as T;
    }

    return new descriptor.implementation() as T;
  }
}

export const diContainer = DIContainer.getInstance();

// ============================================================
// 12. Pipeline Pattern (Middleware)
// ============================================================
interface PipelineContext<T> {
  request: T;
  response?: any;
  next: () => Promise<void>;
}

type Middleware<T> = (context: PipelineContext<T>) => Promise<void>;

class Pipeline<T> {
  private middlewares: Middleware<T>[] = [];

  use(middleware: Middleware<T>) {
    this.middlewares.push(middleware);
  }

  async execute(request: T): Promise<any> {
    let index = 0;
    const context: PipelineContext<T> = {
      request,
      next: async () => {
        index++;
        if (index < this.middlewares.length) {
          await this.middlewares[index](context);
        }
      },
    };

    await this.middlewares[0](context);
    return context.response;
  }
}

// ============================================================
// 13. Saga Pattern (Distributed Transactions)
// ============================================================
interface SagaStep {
  name: string;
  execute(): Promise<void>;
  compensate(): Promise<void>;
}

class Saga {
  private steps: SagaStep[] = [];
  private executedSteps: SagaStep[] = [];

  addStep(step: SagaStep) {
    this.steps.push(step);
    return this;
  }

  async run(): Promise<void> {
    for (const step of this.steps) {
      try {
        await step.execute();
        this.executedSteps.push(step);
      } catch (error) {
        await this.compensate();
        throw error;
      }
    }
  }

  private async compensate(): Promise<void> {
    for (let i = this.executedSteps.length - 1; i >= 0; i--) {
      try {
        await this.executedSteps[i].compensate();
      } catch (error) {
        console.error('Compensation error:', error);
      }
    }
    this.executedSteps = [];
  }
}

// ============================================================
// 14. Specification Pattern
// ============================================================
interface Specification<T> {
  isSatisfiedBy(entity: T): boolean;
  and(spec: Specification<T>): Specification<T>;
  or(spec: Specification<T>): Specification<T>;
  not(): Specification<T>;
}

class ConcreteSpecification<T> implements Specification<T> {
  constructor(private predicate: (entity: T) => boolean) {}

  isSatisfiedBy(entity: T): boolean {
    return this.predicate(entity);
  }

  and(spec: Specification<T>): Specification<T> {
    return new ConcreteSpecification(entity => 
      this.isSatisfiedBy(entity) && spec.isSatisfiedBy(entity)
    );
  }

  or(spec: Specification<T>): Specification<T> {
    return new ConcreteSpecification(entity => 
      this.isSatisfiedBy(entity) || spec.isSatisfiedBy(entity)
    );
  }

  not(): Specification<T> {
    return new ConcreteSpecification(entity => !this.isSatisfiedBy(entity));
  }
}

// ============================================================
// 15. Mediator Pattern (Event Aggregator)
// ============================================================
interface IMediator {
  send<T>(message: T): Promise<any>;
  publish<T>(notification: T): Promise<void>;
}

class Mediator implements IMediator {
  private handlers: Map<string, Array<(message: any) => Promise<any>>> = new Map();

  register<T>(messageType: string, handler: (message: T) => Promise<any>) {
    if (!this.handlers.has(messageType)) {
      this.handlers.set(messageType, []);
    }
    this.handlers.get(messageType)!.push(handler);
  }

  async send<T>(message: T): Promise<any> {
    const messageType = (message as any).constructor.name;
    const handlers = this.handlers.get(messageType) || [];
    
    for (const handler of handlers) {
      try {
        await handler(message);
      } catch (error) {
        console.error('Handler error:', error);
      }
    }
  }

  async publish<T>(notification: T): Promise<void> {
    await this.send(notification);
  }
}

export const mediator = new Mediator();

// CQRS + Repository Pattern + Unit of Work - Enterprise Architecture

type AnyCommand = Command<any>;
type AnyQuery = Query<any>;

// Command base
interface Command<TResult = void> {
  execute(): Promise<TResult>;
}

// Query base
interface Query<TResult> {
  execute(): Promise<TResult>;
}

// Command Handler
interface CommandHandler<TCommand extends AnyCommand, TResult = void> {
  handle(command: TCommand): Promise<TResult>;
}

// Query Handler
interface QueryHandler<TQuery extends AnyQuery, TResult> {
  handle(query: TQuery): Promise<TResult>;
}

// Unit of Work
interface UnitOfWork {
  begin(): void;
  commit(): Promise<void>;
  rollback(): Promise<void>;
  registerNew<T>(entity: T): void;
  registerModified<T>(entity: T): void;
  registerDeleted<T>(entity: T): void;
}

class InMemoryUnitOfWork implements UnitOfWork {
  private newEntities: any[] = [];
  private modifiedEntities: any[] = [];
  private deletedEntities: any[] = [];

  begin(): void {
    this.newEntities = [];
    this.modifiedEntities = [];
    this.deletedEntities = [];
  }

  commit(): Promise<void> {
    return Promise.resolve();
  }

  rollback(): Promise<void> {
    this.newEntities = [];
    this.modifiedEntities = [];
    this.deletedEntities = [];
    return Promise.resolve();
  }

  registerNew<T>(entity: T): void {
    this.newEntities.push(entity);
  }

  registerModified<T>(entity: T): void {
    this.modifiedEntities.push(entity);
  }

  registerDeleted<T>(entity: T): void {
    this.deletedEntities.push(entity);
  }

  getChanges() {
    return {
      new: [...this.newEntities],
      modified: [...this.modifiedEntities],
      deleted: [...this.deletedEntities],
    };
  }
}

// Command Bus
class CommandBus {
  private static instance: CommandBus;
  private handlers = new Map<string, CommandHandler<any>>();

  static getInstance(): CommandBus {
    if (!CommandBus.instance) {
      CommandBus.instance = new CommandBus();
    }
    return CommandBus.instance;
  }

  register<TCommand extends AnyCommand, TResult>(
    commandType: string,
    handler: CommandHandler<TCommand, TResult>
  ): void {
    this.handlers.set(commandType, handler as CommandHandler<any>);
  }

  async execute<TCommand extends AnyCommand, TResult = any>(
    command: TCommand
  ): Promise<TResult> {
    const commandType = command.constructor.name || 'UnknownCommand';
    const handler = this.handlers.get(commandType);
    
    if (!handler) {
      throw new Error(`No handler registered for command: ${commandType}`);
    }

    return handler.handle(command) as Promise<TResult>;
  }
}

// Query Bus
class QueryBus {
  private static instance: QueryBus;
  private handlers = new Map<string, QueryHandler<any, any>>();

  static getInstance(): QueryBus {
    if (!QueryBus.instance) {
      QueryBus.instance = new QueryBus();
    }
    return QueryBus.instance;
  }

  register<TQuery extends AnyQuery, TResult>(
    queryType: string,
    handler: QueryHandler<TQuery, TResult>
  ): void {
    this.handlers.set(queryType, handler);
  }

  async execute<TQuery extends AnyQuery, TResult = any>(
    query: TQuery
  ): Promise<TResult> {
    const queryType = query.constructor.name || 'UnknownQuery';
    const handler = this.handlers.get(queryType);
    
    if (!handler) {
      throw new Error(`No handler registered for query: ${queryType}`);
    }

    return handler.handle(query);
  }
}

