// Performance Hook - Web Vitals Monitoring
// Professional Performance Tracking for Production

import { useEffect, useCallback } from 'react';

interface PerformanceMetrics {
  LCP: number | null; // Largest Contentful Paint
  FID: number | null; // First Input Delay
  CLS: number | null; // Cumulative Layout Shift
  FCP: number | null; // First Contentful Paint
  TTFB: number | null; // Time to First Byte
}

export function usePerformance() {
  const reportWebVitals = useCallback((metrics: PerformanceMetrics) => {
    if (import.meta.env.PROD) {
      // Send to analytics service
      fetch('/api/analytics/performance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(metrics),
      }).catch(console.error);
    } else {
      console.log('Web Vitals:', metrics);
    }
  }, []);

  useEffect(() => {
    // Measure Core Web Vitals
    const metrics: PerformanceMetrics = {
      LCP: null,
      FID: null,
      CLS: null,
      FCP: null,
      TTFB: null,
    };

    // LCP - Largest Contentful Paint
    const lcpObserver = new PerformanceObserver((entryList) => {
      const entries = entryList.getEntries();
      const lastEntry = entries[entries.length - 1];
      metrics.LCP = lastEntry.startTime;
    });
    lcpObserver.observe({ entryTypes: ['largest-contentful-paint'] });

    // FCP - First Contentful Paint
    const fcpObserver = new PerformanceObserver((entryList) => {
      const entries = entryList.getEntries();
      const firstEntry = entries[0];
      metrics.FCP = firstEntry.startTime;
    });
    fcpObserver.observe({ entryTypes: ['first-contentful-paint'] });

    // TTFB - Time to First Byte
    const ttfbObserver = new PerformanceObserver((entryList) => {
      const entries = entryList.getEntries();
      const navigationEntry = entries.find((e) => e.name === 'navigation');
      if (navigationEntry) {
        // Type assertion for browser-specific PerformanceNavigationTiming
        const navEntry = navigationEntry as PerformanceNavigationTiming;
        metrics.TTFB = navEntry.responseStart;
      }
    });
    ttfbObserver.observe({ entryTypes: ['navigation'] });

    // CLS - Cumulative Layout Shift
    let clsValue = 0;
    const clsObserver = new PerformanceObserver((entryList) => {
      for (const entry of entryList.getEntries()) {
        if (!(entry as unknown as { hadRecentInput?: boolean }).hadRecentInput) {
          clsValue += (entry as unknown as { value?: number }).value || 0;
        }
      }
      metrics.CLS = clsValue;
    });
    clsObserver.observe({ entryTypes: ['layout-shift'] });

    // FID - First Input Delay
    const fidObserver = new PerformanceObserver((entryList) => {
      const entries = entryList.getEntries();
      const firstEntry = entries[0];
      if (firstEntry) {
        // Type assertion for browser-specific PerformanceEventTiming
        const eventEntry = firstEntry as PerformanceEventTiming;
        metrics.FID = eventEntry.processingStart - eventEntry.startTime;
        reportWebVitals(metrics);
      }
    });
    fidObserver.observe({ entryTypes: ['first-input'] });

    // Cleanup
    return () => {
      lcpObserver.disconnect();
      fcpObserver.disconnect();
      ttfbObserver.disconnect();
      clsObserver.disconnect();
      fidObserver.disconnect();
    };
  }, [reportWebVitals]);

  return { reportWebVitals };
}

// Performance Marks Utility
export function markPerformance(name: string) {
  if (typeof performance !== 'undefined') {
    performance.mark(name);
  }
}

export function measurePerformance(name: string, startMark: string, endMark: string) {
  if (typeof performance !== 'undefined') {
    performance.measure(name, startMark, endMark);
    return performance.getEntriesByName(name)[0]?.duration || 0;
  }
  return 0;
}

import { useEffect, useState } from 'react';

import { supabase } from '../lib/supabase';

export function useRealtimeMessages() {
  const [newMessage, setNewMessage] = useState<any | null>(null);
  const [updatedMessage, setUpdatedMessage] = useState<any | null>(null);

  useEffect(() => {
    // التأكد من أن supabase مُعدّ
    if (!supabase) return;

    const channel = supabase
      .channel('messages-realtime')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'messages',
        },
        (payload: any) => {
          setNewMessage(payload.new);
          // طلب إشعار المتصفح
          if (Notification.permission === 'granted') {
            new Notification('📩 رسالة جديدة', {
              body: `من: ${payload.new.name}`,
              icon: '/favicon.svg',
            });
          }
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'messages',
        },
        (payload: any) => {
          setUpdatedMessage(payload.new);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  return { newMessage, updatedMessage };
}

// Sanity helpers for image URLs and content processing
import { getRandomImage } from "@/utils/imageUtils";

const fallbackImages = [
  '/images/defaults/project-relief.svg',
  '/images/defaults/project-education.svg',
  '/images/defaults/project-water.svg',
];

export function getSanityImageUrl(
  source: any,
  width: number = 800,
  height: number = 600,
  fallbackCategory?: string
): string {
  // Check if source exists and has valid asset reference
  if (!source || !source.asset || !source.asset._ref) {
    return fallbackCategory 
      ? getRandomImage(fallbackCategory) 
      : fallbackImages[0];
  }

  try {
    // Build Sanity CDN image URL
    const ref = source.asset._ref;
    // Extract image ID from Sanity reference
    const imageId = ref.replace('image-', '');
    
    return `https://cdn.sanity.io/images/xd0ohyiz/production/${imageId}?w=${width}&h=${height}&auto=format&q=85&fit=crop`;
  } catch (error) {
    console.warn('Error building Sanity image URL:', error);
    return fallbackCategory 
      ? getRandomImage(fallbackCategory) 
      : fallbackImages[0];
  }
}

// Helper to process project data for display
export function processProjectData(project: any) {
  const category = project.category || 'عام';
  
  return {
    id: project._id || project.id,
    title: project.title || 'مشروع بدون عنوان',
    description: project.description || project.excerpt || 'لا يوجد وصف متوفر',
    category,
    status: project.status || 'pending',
    beneficiaries: typeof project.beneficiaries === 'number' 
      ? project.beneficiaries.toLocaleString() 
      : project.beneficiaries || '0',
    progress: project.progress || 0,
    location: project.location || 'غير محدد',
    budget: project.budget || 'غير محدد',
    image: project.mainImage 
      ? getSanityImageUrl(project.mainImage, 800, 600, category)
      : getRandomImage(category),
    featured: project.featured || false,
  };
}

export default {
  getSanityImageUrl,
  processProjectData,
};

