const App = lazy(() => import("./app/App"));

// ============================================================
// Main App - progress bar tracks REAL module readiness.
// No artificial delays: interactive as soon as the shell mounts.
// ============================================================
function AppWithProgress() {
  const { percentage, message, isComplete, isReady, markInteractive } = usePageProgress('hero');
  const [isInteractive, setIsInteractive] = useState(false);

  useEffect(() => {
    // Mark interactive immediately once the shell is mounted
    markInteractive();
    setIsInteractive(true);
  }, [markInteractive]);

  return (
    <>
      <AdvancedProgressBar
        percentage={percentage}
        message={message}
        isComplete={isComplete || isInteractive}
        isReady={isReady && isInteractive}
        showAyah={true}
      />
      <ScrollProgressIndicator />
      <OfflineIndicator />
      <Suspense fallback={<HeroSkeleton />}>
        <ErrorBoundary>
          <App />
        </ErrorBoundary>
      </Suspense>
    </>
  );
}

