// src/shared/hooks/useDynamicContent.ts
import { useState, useEffect, useCallback } from 'react';

import { contentBridge } from '@/shared/services/content-bridge.service';

interface UseDynamicContentOptions<T> {
  contentType: string;
  initialData?: T[];
  enableRealtime?: boolean;
  refreshInterval?: number;
}

export function useDynamicContent<T = any>({
  contentType,
  initialData,
  enableRealtime = false,
  refreshInterval = 300000 // 5 دقائق
}: UseDynamicContentOptions<T>) {
  const [data, setData] = useState<T[]>(initialData || []);
  const [isLoading, setIsLoading] = useState(!initialData);
  const [source, setSource] = useState<'static' | 'sanity' | 'hybrid'>('static');
  const [error, setError] = useState<Error | null>(null);

  const loadContent = useCallback(async () => {
    try {
      const result = await contentBridge.getContent<T>(contentType as any);
      setData(result.data);
      setSource(result.source);
      setError(result.error ? new Error(result.error) : null);
    } catch (err) {
      setError(err as Error);
      // استخدام المحتوى الاحتياطي
      if (initialData) {
        setData(initialData);
      }
    } finally {
      setIsLoading(false);
    }
  }, [contentType, initialData]);

  useEffect(() => {
    loadContent();

    if (enableRealtime) {
      const interval = setInterval(loadContent, refreshInterval);
      return () => clearInterval(interval);
    }
  }, [loadContent, enableRealtime, refreshInterval]);

  return {
    data,
    isLoading,
    source,
    error,
    isDynamic: source === 'sanity' || source === 'hybrid',
    refresh: loadContent
  };
}

// Dynamic Contrast Hook for WCAG 2.1 AAA Accessibility Compliance
// خطاف تفاعلي لفحص وتعديل تباين العناوين والأزرار ديناميكياً لتلبية معيار WCAG 2.1 AAA

import { useEffect, useRef } from "react";
import { applyDynamicAAAContrast, getOptimalAAAColor } from "@/shared/utils/wcagContrast";

export interface DynamicContrastOptions {
  selector?: string;
  enabled?: boolean;
  onAuditComplete?: (auditedCount: number) => void;
}

/**
 * Custom Hook that scans headings, buttons, badges, and labels,
 * dynamically adjusting text color based on section background & pattern opacity.
 */
export function useDynamicContrast<T extends HTMLElement = HTMLDivElement>({
  selector = "h1, h2, h3, h4, h5, button, a.btn-primary, a.btn-gold, .section-subtitle, .badge-gold",
  enabled = true,
  onAuditComplete,
}: DynamicContrastOptions = {}) {
  const containerRef = useRef<T | null>(null);
  const auditTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (!enabled) return;

    const auditElements = () => {
      if (auditTimeoutRef.current) return;

      auditTimeoutRef.current = setTimeout(() => {
        const root = containerRef.current || document.body;
        const elements = root.querySelectorAll<HTMLElement>(selector);

        let auditedCount = 0;
        elements.forEach((el) => {
          applyDynamicAAAContrast(el);
          auditedCount++;
        });

        if (onAuditComplete) {
          onAuditComplete(auditedCount);
        }

        auditTimeoutRef.current = null;
      }, 100);
    };

    // Run audit immediately and on resize/theme toggle
    auditElements();

    const observer = new MutationObserver(() => {
      auditElements();
    });

    if (containerRef.current) {
      observer.observe(containerRef.current, {
        childList: true,
        subtree: true,
      });
    }

    window.addEventListener("resize", auditElements);

    return () => {
      observer.disconnect();
      window.removeEventListener("resize", auditElements);
    };
  }, [selector, enabled, onAuditComplete]);

  return containerRef;
}

export default useDynamicContrast;

// React Hook for notifications - useNotifications.ts
import { useState, useEffect } from 'react';

import { notificationService } from '@/shared/services/notification.service';

interface NotificationOptions {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  data?: Record<string, any>;
  actions?: { action: string; title: string }[];
  tag?: string;
  requireInteraction?: boolean;
}

export function useNotifications() {
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (notificationService.isSupported()) {
      setPermission(Notification.permission);
      notificationService.isSubscribed().then(setIsSubscribed);
    }
  }, []);

  const subscribe = async () => {
    setLoading(true);
    try {
      const sub = await notificationService.subscribe();
      if (sub) {
        setIsSubscribed(true);
      }
    } catch (error) {
      console.error('Subscription failed:', error);
    } finally {
      setLoading(false);
    }
  };

  const unsubscribe = async () => {
    setLoading(true);
    await notificationService.unsubscribe();
    setIsSubscribed(false);
    setLoading(false);
  };

  const notify = async (options: NotificationOptions) => {
    await notificationService.showLocalNotification(options);
  };

  return { permission, isSubscribed, loading, subscribe, unsubscribe, notify };
}

// PWA Install Hook - خطاف تثبيت التطبيق
// يلتقط حدث beforeinstallprompt مبكراً على مستوى الوحدة
// حتى لو صدر قبل تحميل المكوّن (مشكلة شائعة في PWA)
import { useEffect, useState, useCallback } from "react";

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>;
}

// ── التقاط عالمي مبكر ──────────────────────────────────────
let capturedPrompt: BeforeInstallPromptEvent | null = null;
type Waiter = (e: BeforeInstallPromptEvent | null) => void;
const waiters = new Set<Waiter>();

if (typeof window !== "undefined") {
  window.addEventListener("beforeinstallprompt", (e) => {
    e.preventDefault();
    capturedPrompt = e as BeforeInstallPromptEvent;
    waiters.forEach((w) => w(capturedPrompt));
  });
  window.addEventListener("appinstalled", () => {
    capturedPrompt = null;
    waiters.forEach((w) => w(null));
  });
}

export type InstallOutcome = "accepted" | "dismissed" | "unavailable";

export function usePwaInstall() {
  const [deferred, setDeferred] = useState<BeforeInstallPromptEvent | null>(capturedPrompt);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isStandalone, setIsStandalone] = useState(false);
  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    const standalone =
      window.matchMedia("(display-mode: standalone)").matches ||
      (navigator as any).standalone === true;
    setIsStandalone(standalone);
    setIsIOS(/iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream);

    const waiter: Waiter = (e) => setDeferred(e);
    waiters.add(waiter);
    const onInstalled = () => setIsInstalled(true);
    window.addEventListener("appinstalled", onInstalled);

    return () => {
      waiters.delete(waiter);
      window.removeEventListener("appinstalled", onInstalled);
    };
  }, []);

  const promptInstall = useCallback(async (): Promise<InstallOutcome> => {
    if (!deferred) return "unavailable";
    await deferred.prompt();
    const { outcome } = await deferred.userChoice;
    if (outcome === "accepted") setIsInstalled(true);
    setDeferred(null);
    return outcome;
  }, [deferred]);

  return {
    canInstall: !!deferred,
    promptInstall,
    isInstalled,
    isStandalone,
    isIOS,
  };
}

// useResponsive - نظام متكامل للتحكم في التجاوب
import { useState, useEffect, useCallback } from 'react';

type Breakpoint = 'mobile' | 'tablet' | 'desktop' | 'wide';
type DeviceType = 'phone' | 'tablet' | 'laptop' | 'desktop';
type Orientation = 'portrait' | 'landscape';

interface ResponsiveState {
  breakpoint: Breakpoint;
  device: DeviceType;
  orientation: Orientation;
  width: number;
  height: number;
  isMobile: boolean;
  isTablet: boolean;
  isDesktop: boolean;
  isPortrait: boolean;
  isLandscape: boolean;
  isTouchDevice: boolean;
  hasNotch: boolean;
  pixelRatio: number;
}

// Cache for SSR
let cachedState: ResponsiveState | null = null;

function getResponsiveState(): ResponsiveState {
  if (typeof window === 'undefined') {
    return cachedState || {
      breakpoint: 'desktop',
      device: 'laptop',
      orientation: 'landscape',
      width: 1024,
      height: 768,
      isMobile: false,
      isTablet: false,
      isDesktop: true,
      isPortrait: false,
      isLandscape: true,
      isTouchDevice: false,
      hasNotch: false,
      pixelRatio: 1
    };
  }

  const width = window.innerWidth;
  const height = window.innerHeight;
  const orientation: Orientation = width > height ? 'landscape' : 'portrait';
  const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;

  let breakpoint: Breakpoint;
  if (width < 640) breakpoint = 'mobile';
  else if (width < 1024) breakpoint = 'tablet';
  else if (width < 1440) breakpoint = 'desktop';
  else breakpoint = 'wide';

  let device: DeviceType;
  if (width < 640) device = 'phone';
  else if (width < 1024) device = 'tablet';
  else if (width < 1440) device = 'laptop';
  else device = 'desktop';

  const hasNotch = window.matchMedia('(display-cutout: viewport-fit)').matches;

  const state: ResponsiveState = {
    breakpoint,
    device,
    orientation,
    width,
    height,
    isMobile: breakpoint === 'mobile',
    isTablet: breakpoint === 'tablet',
    isDesktop: breakpoint === 'desktop' || breakpoint === 'wide',
    isPortrait: orientation === 'portrait',
    isLandscape: orientation === 'landscape',
    isTouchDevice,
    hasNotch,
    pixelRatio: window.devicePixelRatio || 1
  };

  cachedState = state;
  return state;
}

export function useResponsive(): ResponsiveState {
  const [state, setState] = useState<ResponsiveState>(() => getResponsiveState());

  useEffect(() => {
    let ticking = false;
    
    const handleResize = () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          setState(getResponsiveState());
          ticking = false;
        });
        ticking = true;
      }
    };
    
    const handleOrientationChange = () => {
      setTimeout(handleResize, 100);
    };
    
    window.addEventListener('resize', handleResize);
    window.addEventListener('orientationchange', handleOrientationChange);
    
    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('orientationchange', handleOrientationChange);
    };
  }, []);
  
  return state;
}

/**
