  const [projects, setProjects] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    
    async function fetchProjects() {
      setLoading(true);
      try {
        const data = await sanityService.getProjects();
        if (!cancelled) {
          setProjects(data);
          setError(null);
