        ],
      },
      'viewer@rbdcye.org': {
        name: 'خالد المشاهد',
        role: 'VIEWER',
        password: 'rbdcye123',
        permissions: [
          { resource: 'news', actions: ['read'] },
          { resource: 'projects', actions: ['read'] },
          { resource: 'reports', actions: ['read'] },
        ],
      },
    };

    const mock = MOCK_USERS[email];
    if (mock && password === mock.password) {
