interface NotificationOptions {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  data?: Record<string, unknown>;
  actions?: { action: string; title: string }[];
  tag?: string;
  requireInteraction?: boolean;
}

interface Subscription {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

// VAPID Public Key (should be from environment)
const VAPID_PUBLIC_KEY = import.meta.env.VITE_VAPID_PUBLIC_KEY || '';

class NotificationService {
  private static instance: NotificationService;
  private swRegistration: ServiceWorkerRegistration | null = null;
  private subscription: Subscription | null = null;

  private constructor() {
    this.init();
  }

  static getInstance(): NotificationService {
    if (!NotificationService.instance) {
      NotificationService.instance = new NotificationService();
    }
    return NotificationService.instance;
  }

  // Initialize service worker and notifications
  private async init() {
    if ('serviceWorker' in navigator && 'PushManager' in window) {
      try {
        this.swRegistration = await navigator.serviceWorker.register('/sw.js', {
          scope: '/',
        });
        console.log('Service Worker registered for notifications');
      } catch (error) {
        console.warn('Failed to register service worker:', error);
      }
    }
  }

  // Request permission for notifications
  async requestPermission(): Promise<NotificationPermission> {
    if (!('Notification' in window)) {
      return 'default';
    }

    const permission = await Notification.requestPermission();
    return permission;
  }

  // Check if notifications are supported
  isSupported(): boolean {
    return 'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window;
  }

  // Get current subscription
  async getSubscription(): Promise<Subscription | null> {
    if (!this.swRegistration) return null;

    try {
      const sub = await this.swRegistration.pushManager.getSubscription();
      if (sub) {
        const p256dhKey = sub.getKey('p256dh');
        const authKey = sub.getKey('auth');
        
        this.subscription = {
          endpoint: sub.endpoint,
          keys: {
            p256dh: p256dhKey ? this.arrayBufferToBase64(p256dhKey) : '',
            auth: authKey ? this.arrayBufferToBase64(authKey) : '',
          },
        };
      }
      return this.subscription;
    } catch {
      return null;
    }
  }

  // Subscribe to push notifications
  async subscribe(): Promise<Subscription | null> {
    if (!this.swRegistration) {
      throw new Error('Service Worker not registered');
    }

    const permission = await this.requestPermission();
    if (permission !== 'granted') {
      throw new Error('Notification permission denied');
    }

    try {
      const sub = await this.swRegistration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.base64ToUint8Array(VAPID_PUBLIC_KEY) as BufferSource,
      });

      const p256dhKey = sub.getKey('p256dh');
      const authKey = sub.getKey('auth');
      
      this.subscription = {
        endpoint: sub.endpoint,
        keys: {
          p256dh: p256dhKey ? this.arrayBufferToBase64(p256dhKey) : '',
          auth: authKey ? this.arrayBufferToBase64(authKey) : '',
        },
      };

      // Send subscription to server
      await this.sendSubscriptionToServer(this.subscription);

      return this.subscription;
    } catch (error) {
      console.error('Failed to subscribe to push notifications:', error);
      return null;
    }
  }

  // Unsubscribe from push notifications
  async unsubscribe(): Promise<void> {
    if (!this.swRegistration) return;

    try {
      const sub = await this.swRegistration.pushManager.getSubscription();
      if (sub) {
        await sub.unsubscribe();
      }
      this.subscription = null;
    } catch (error) {
      console.error('Failed to unsubscribe:', error);
    }
  }

  // Show local notification
  async showLocalNotification(options: NotificationOptions): Promise<void> {
    if (!this.isSupported()) return;

    const permission = await this.requestPermission();
    if (permission !== 'granted') return;

    if (this.swRegistration && this.swRegistration.active) {
      this.swRegistration.active.postMessage({
        type: 'SHOW_NOTIFICATION',
        payload: options,
      });
    } else {
      // Fallback to regular notification
      new Notification(options.title, {
        body: options.body,
        icon: options.icon || '/favicon.svg',
        badge: options.badge,
        data: options.data,
      });
    }
  }

  // Send subscription to server
  private async sendSubscriptionToServer(subscription: Subscription): Promise<void> {
    try {
      await fetch('/api/notifications/subscribe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(subscription),
      });
    } catch (error) {
      console.warn('Failed to save subscription to server:', error);
    }
  }

  // Utility: Convert base64 to Uint8Array
  private base64ToUint8Array(base64String: string): Uint8Array {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  // Convert ArrayBuffer to Base64 string
  private arrayBufferToBase64(buffer: ArrayBuffer): string {
    let binary = '';
    const bytes = new Uint8Array(buffer);
    bytes.forEach((byte) => {
      binary += String.fromCharCode(byte);
    });
    return window.btoa(binary);
  }

  // Check if user is subscribed
  async isSubscribed(): Promise<boolean> {
    const subscription = await this.getSubscription();
    return !!subscription;
  }
}

export const notificationService = NotificationService.getInstance();

// Payment Service - Stripe Integration
// هذا الملف يوفر دمج Stripe للتبرعات الحقيقية

import { useState } from "react";

// استعارة لأنواع Stripe على النافذ
declare global {
  interface Window {
    Stripe: any;
  }
}

interface PaymentConfig {
  publicKey: string;
  currency: string;
  country: string;
}

interface DonationData {
  amount: number;
  donor: string;
  email?: string;
  phone?: string;
  project?: string;
  type?: 'once' | 'monthly' | 'yearly';
  message?: string;
}

// تكوين Stripe (يجب إضافة المفاتيح في .env)
const getStripeConfig = (): PaymentConfig => ({
  publicKey: import.meta.env.VITE_STRIPE_PUBLIC_KEY || '',
  currency: 'usd',
  country: 'YE', // اليمن
});

// تحميل Stripe.js
const loadStripe = async () => {
  const config = getStripeConfig();
  if (!config.publicKey) {
    throw new Error('Stripe public key not configured. Please add VITE_STRIPE_PUBLIC_KEY to your .env file');
  }
  
  // تحقق من التحميل مسبقاً
  if (window.Stripe) {
    return window.Stripe;
  }
  
  // تحميل Stripe من CDN
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://js.stripe.com/v3/';
    script.async = true;
    
    script.onload = () => {
      if (window.Stripe) {
        resolve(window.Stripe);
      } else {
        reject(new Error('Failed to load Stripe from window'));
      }
    };
    script.onerror = () => reject(new Error('Failed to load Stripe script'));
    
    document.head.appendChild(script);
  });
};

// إنشاء Checkout Session على الخادم
export async function createCheckoutSession(data: DonationData): Promise<string> {
  const response = await fetch('/api/create-checkout-session', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      amount: Math.round(data.amount * 100), // Stripe يستخدم السنتات
      currency: getStripeConfig().currency,
      donor: data.donor,
      email: data.email,
      phone: data.phone,
      project: data.project,
      type: data.type,
      successUrl: `${window.location.origin}/donate?success=1`,
      cancelUrl: `${window.location.origin}/donate`,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Failed to create checkout session: ${errorText}`);
  }

  const { sessionId } = await response.json();
  return sessionId;
}

// فتح نافذة الدفع
export async function openPaymentModal(data: DonationData): Promise<void> {
  const StripeConstructor = await loadStripe();
  const stripe = StripeConstructor(getStripeConfig().publicKey);

  // إنشاء Checkout Session
  const sessionId = await createCheckoutSession(data);
  
  // التوجه إلى Stripe Checkout
  const result = await stripe.redirectToCheckout({ sessionId });
  
  if (result.error) {
    throw new Error(result.error.message);
  }
}

// معالجة التبرع
export async function processDonation(data: DonationData): Promise<void> {
  await openPaymentModal(data);
}

// Hook لاستخدام الخدمة
export function usePayment() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const donate = async (data: DonationData) => {
    setLoading(true);
    setError(null);
    try {
      await processDonation(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Payment failed');
    } finally {
      setLoading(false);
    }
  };

  return { donate, loading, error };
}

