// Error Handling Utilities - أدوات معالجة الأخطاء الموحدة
export interface ApiError {
  message: string;
  code?: string;
  status?: number;
  details?: any;
}

// Create a standardized API error
export function createApiError(message: string, status?: number, code?: string, details?: any): ApiError {
  return {
    message,
    status,
    code: code || status?.toString() || 'UNKNOWN_ERROR',
    details,
  };
}

// Handle API response errors
export async function handleApiResponse<T>(response: Response): Promise<T> {
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw createApiError(
      errorData.message || `HTTP Error ${response.status}`,
      response.status,
      errorData.code
    );
  }
  return response.json();
}

// Retry with exponential backoff
export async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries = 3,
  baseDelay = 1000
): Promise<T> {
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));
      
      if (attempt < maxRetries - 1) {
        const delay = baseDelay * Math.pow(2, attempt);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('Operation failed after retries');
}

// Log error for monitoring
export function logError(error: Error | ApiError, context?: string) {
  const errorInfo = {
    message: error.message,
    stack: error instanceof Error ? error.stack : undefined,
    context,
    timestamp: new Date().toISOString(),
  };
  
  // Send to monitoring service if available
  if (typeof console !== 'undefined') {
    console.error('[Error]', errorInfo);
  }
}

// Get user-friendly error message
export function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  if (typeof error === 'string') {
    return error;
  }
  return 'حدث خطأ غير متوقع';
}

export class AppError extends Error {
  constructor(
    public code: string,
    message: string,
    public statusCode: number = 500,
    public details?: Record<string, any>
  ) {
    super(message);
    this.name = 'AppError';
  }
}

export const ErrorCodes = {
  NETWORK_ERROR: 'NETWORK_ERROR',
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  NOT_FOUND: 'NOT_FOUND',
  UNAUTHORIZED: 'UNAUTHORIZED',
  FORBIDDEN: 'FORBIDDEN',
  SERVER_ERROR: 'SERVER_ERROR',
  TIMEOUT: 'TIMEOUT',
} as const;

export const handleApiError = (error: unknown): AppError => {
  if (error instanceof AppError) {
    return error;
  }
  if (error instanceof Error) {
    if (error.message.includes('fetch') || error.message.includes('Network')) {
      return new AppError(ErrorCodes.NETWORK_ERROR, 'فشل الاتصال بالخادم', 503);
    }
    return new AppError(ErrorCodes.SERVER_ERROR, error.message, 500);
  }
  return new AppError(ErrorCodes.SERVER_ERROR, 'حدث خطأ غير متوقع', 500);
};

export const withRetry = async <T>(
  fn: () => Promise<T>,
  retries: number = 3,
  delay: number = 1000
): Promise<T> => {
  try {
    return await fn();
  } catch (error) {
    if (retries <= 0) throw error;
    await new Promise(resolve => setTimeout(resolve, delay));
    return withRetry(fn, retries - 1, delay * 2);
  }
};

export const getUserFriendlyMessage = (error: AppError): string => {
  switch (error.code) {
    case ErrorCodes.NETWORK_ERROR:
      return 'تأكد من اتصالك بالإنترنت وحاول مرة أخرى';
    case ErrorCodes.NOT_FOUND:
      return 'العنصر المطلوب غير موجود';
    case ErrorCodes.UNAUTHORIZED:
      return 'يرجى تسجيل الدخول للمتابعة';
    case ErrorCodes.FORBIDDEN:
      return 'ليس لديك صلاحية الوصول لهذا المحتوى';
    case ErrorCodes.TIMEOUT:
      return 'انتهت مهلة الطلب، يرجى المحاولة مرة أخرى';
    default:
      return 'حدث خطأ ما، يرجى المحاولة لاحقاً';
  }
};

import { ComponentType, lazy, LazyExoticComponent } from 'react';

/**
 * Lazy loads a React component with automatic exponential retry
 * to handle temporary network dropouts, container redeployments,
 * or stale chunk hashes after deployment builds.
 */
export function lazyWithRetry<T extends ComponentType<any>>(
  componentImport: () => Promise<{ default: T }>,
  retries = 5,
  interval = 1000
): LazyExoticComponent<T> {
  return lazy(() =>
    new Promise<{ default: T }>((resolve, reject) => {
      const attempt = (remaining: number) => {
        componentImport()
          .then((res) => {
            if (typeof window !== 'undefined') {
              window.sessionStorage.removeItem('chunk_retry_reloaded');
            }
            resolve(res);
          })
          .catch((error) => {
            // Check if error is a dynamic import / chunk load failure
            const isChunkError =
              error?.message?.includes('Failed to fetch dynamically imported module') ||
              error?.message?.includes('Importing a module script failed') ||
              error?.name === 'ChunkLoadError';

            if (remaining <= 0) {
              // If this is a chunk loading error and we haven't reloaded the page yet for this session,
              // automatically reload to fetch fresh bundle manifests
              if (isChunkError && typeof window !== 'undefined' && !window.sessionStorage.getItem('chunk_retry_reloaded')) {
                window.sessionStorage.setItem('chunk_retry_reloaded', 'true');
                window.location.reload();
                return;
              }
              reject(error);
              return;
            }
            setTimeout(() => {
              attempt(remaining - 1);
            }, interval);
          });
      };
      attempt(retries);
    })
  );
}

export default lazyWithRetry;

export const reportWebVitals = (metric: { name: string; value: number; rating: string }) => {
  if (typeof window !== 'undefined') {
    const body = JSON.stringify(metric);
    const url = '/api/v1/analytics/web-vitals';
    if (navigator.sendBeacon) {
      navigator.sendBeacon(url, body);
    } else {
      fetch(url, { body, method: 'POST', keepalive: true });
    }
  }
};

export const measurePerformance = () => {
  if (typeof window !== 'undefined' && 'PerformanceObserver' in window) {
    try {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.entryType === 'largest-contentful-paint') {
            reportWebVitals({ name: 'LCP', value: (entry as any).startTime, rating: (entry as any).rating || 'good' });
          }
          if (entry.entryType === 'first-input') {
            reportWebVitals({ name: 'FID', value: (entry as any).processingStart - (entry as any).startTime, rating: 'good' });
