type LogLevel = 'debug' | 'info' | 'warn' | 'error' | 'fatal';

interface LogEntry {
  timestamp: string;
  level: LogLevel;
  message: string;
  data?: any;
  userId?: string;
  sessionId?: string;
  url?: string;
  userAgent?: string;
}

class Logger {
  private static LOG_PREFIX = '[rbdcye]';
  private static STORAGE_KEY = 'app_logs';
  private static MAX_LOGS = 100;

  // تنسيق الرسالة
  private format(level: LogLevel, message: string, data?: any): LogEntry {
    return {
      timestamp: new Date().toISOString(),
      level,
      message: `${Logger.LOG_PREFIX} ${message}`,
      data,
      userId: this.getUserId(),
      sessionId: this.getSessionId(),
      url: typeof window !== 'undefined' ? window.location.href : undefined,
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : undefined,
    };
  }

  // الحصول على معرف المستخدم
  private getUserId(): string | undefined {
    try {
      const user = localStorage.getItem('auth_user');
      if (user) {
        const parsed = JSON.parse(user);
        return parsed.id;
      }
    } catch {
      // Ignore errors
    }
    return undefined;
  }

  // الحصول على معرف الجلسة
  private getSessionId(): string | undefined {
    try {
      let sessionId = sessionStorage.getItem('session_id');
      if (!sessionId) {
        sessionId = `sess_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
        sessionStorage.setItem('session_id', sessionId);
      }
      return sessionId;
    } catch {
      // Ignore errors
    }
    return undefined;
  }

  // حفظ السجل في التخزين المحلي
  private persist(entry: LogEntry) {
    try {
      const logs = this.getLogs();
      logs.push(entry);
      
      // الاحتفاظ بآخر 100 سجل فقط
      if (logs.length > Logger.MAX_LOGS) {
        logs.splice(0, logs.length - Logger.MAX_LOGS);
      }

      localStorage.setItem(Logger.STORAGE_KEY, JSON.stringify(logs));
    } catch {
      // تجاهل أخطاء التخزين
    }
  }

  // الحصول على السجلات
  private getLogs(): LogEntry[] {
    try {
      const logs = localStorage.getItem(Logger.STORAGE_KEY);
      return logs ? JSON.parse(logs) : [];
    } catch {
      return [];
    }
  }

  // مسح السجلات
  clearLogs() {
    try {
      localStorage.removeItem(Logger.STORAGE_KEY);
    } catch {
      // Ignore errors
    }
  }

  // --- مستويات السجل ---

  debug(message: string, data?: any) {
    const entry = this.format('debug', message, data);
    console.debug(entry);
    // لا نحفظ debug في التخزين المحلي
  }

  info(message: string, data?: any) {
    const entry = this.format('info', message, data);
    console.log(entry);
    this.persist(entry);
  }

  warn(message: string, data?: any) {
    const entry = this.format('warn', message, data);
    console.warn(entry);
    this.persist(entry);
  }

  error(message: string, error?: Error | unknown, data?: any) {
    const entry = this.format('error', message, {
      ...data,
      error: error instanceof Error ? {
        name: error.name,
        message: error.message,
        stack: error.stack,
      } : error,
    });
    console.error(entry);
    this.persist(entry);

    // إرسال لخدمة المراقبة الخارجية (Sentry, etc.)
    this.sendToExternalService(entry);
  }

  fatal(message: string, error?: Error | unknown, data?: any) {
    const entry = this.format('fatal', message, {
      ...data,
      error: error instanceof Error ? {
        name: error.name,
        message: error.message,
        stack: error.stack,
      } : error,
    });
    console.error(entry);
    this.persist(entry);

    // إرسال فوري لخدمة المراقبة
    this.sendToExternalService(entry, true);
  }

  // --- إرسال لخدمة خارجية ---
  private async sendToExternalService(entry: LogEntry, isFatal: boolean = false) {
    // يمكن إضافة Sentry هنا
    // يمكن إضافة LogRocket هنا
    // يمكن إضافة خدمة مخصصة هنا
    
    // مثال: إرسال لـ Sentry
    // if (typeof Sentry !== 'undefined') {
    //   Sentry.captureException(new Error(entry.message), {
    //     level: entry.level,
    //     extra: entry.data,
    //   });
    // }

    // أو إرسال لـ API مخصص
    if (isFatal && typeof navigator !== 'undefined' && 'sendBeacon' in navigator) {
      navigator.sendBeacon('/api/logs', JSON.stringify(entry));
    }
  }

  // --- أدوات مساعدة ---

  // قياس الأداء
  measure<T>(label: string, fn: () => T | Promise<T>): T | Promise<T> {
    const start = performance.now();
    
    try {
      const result = fn();
      
      if (result instanceof Promise) {
        return result.finally(() => {
          const duration = performance.now() - start;
          this.info(`Performance: ${label}`, { duration: `${duration.toFixed(2)}ms` });
        });
      }
      
      const duration = performance.now() - start;
      this.info(`Performance: ${label}`, { duration: `${duration.toFixed(2)}ms` });
      return result;
    } catch (error) {
      const duration = performance.now() - start;
      this.error(`Error in ${label}`, error as Error, { duration: `${duration.toFixed(2)}ms` });
      throw error;
    }
  }

  // تتبع المسار (Breadcrumbs)
  leaveBreadcrumb(category: string, message: string, data?: any) {
    this.debug(`[Breadcrumb] ${category}: ${message}`, data);
  }

  // تعيين سياق المستخدم
  setUserContext(userId: string, email: string, role: string) {
    try {
      sessionStorage.setItem('user_context', JSON.stringify({
        userId,
        email,
        role,
        timestamp: new Date().toISOString(),
      }));
    } catch {
      // Ignore errors
    }
  }

  // مسح سياق المستخدم
  clearUserContext() {
    try {
      sessionStorage.removeItem('user_context');
    } catch {
      // Ignore errors
    }
  }
}

// تصدير instance واحد (Singleton)
export const logger = new Logger();

// تصدير أنواع
export type { LogLevel, LogEntry };

export interface PerformanceMetric {
  name: string;
  value: number;
  rating: 'good' | 'needs-improvement' | 'poor';
  delta: number;
  id: string;
}

export interface WebVitals {
  FCP?: PerformanceMetric;
  LCP?: PerformanceMetric;
  FID?: PerformanceMetric;
  CLS?: PerformanceMetric;
  INP?: PerformanceMetric;
  TTFB?: PerformanceMetric;
}

class PerformanceMonitor {
  private static instance: PerformanceMonitor;
  private metrics: Map<string, PerformanceMetric> = new Map();
  private observers: PerformanceObserver[] = [];

  static getInstance(): PerformanceMonitor {
    if (!PerformanceMonitor.instance) {
      PerformanceMonitor.instance = new PerformanceMonitor();
    }
    return PerformanceMonitor.instance;
  }

  init() {
    if (typeof window === 'undefined') return;

    this.observeNavigation();
    this.observePaint();
    this.observeLayoutShifts();
    this.observeInteractions();
    this.observeResourceTiming();
  }

  private observeNavigation() {
    try {
      const navEntry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
      if (navEntry) {
        this.metrics.set('TTFB', {
          name: 'TTFB',
          value: navEntry.responseStart,
          rating: this.rateMetric('TTFB', navEntry.responseStart),
          delta: navEntry.responseStart,
          id: this.generateId(),
        });
      }
    } catch (error) {
      console.error('Navigation observation error:', error);
    }
  }

  private observePaint() {
    try {
      const paintObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.name === 'first-contentful-paint') {
            this.metrics.set('FCP', {
              name: 'FCP',
              value: entry.startTime,
              rating: this.rateMetric('FCP', entry.startTime),
              delta: entry.startTime,
              id: this.generateId(),
            });
          }
        }
      });
      paintObserver.observe({ type: 'paint', buffered: true });
      this.observers.push(paintObserver);
    } catch (error) {
      console.error('Paint observation error:', error);
    }
  }

  private observeLayoutShifts() {
    try {
      const clsObserver = new PerformanceObserver((list) => {
        let clsValue = 0;
        for (const entry of list.getEntries()) {
          if (!(entry as any).hadRecentInput) {
            clsValue += (entry as any).value;
          }
        }
        this.metrics.set('CLS', {
          name: 'CLS',
          value: clsValue,
          rating: this.rateMetric('CLS', clsValue),
          delta: clsValue,
          id: this.generateId(),
        });
      });
      clsObserver.observe({ type: 'layout-shift', buffered: true });
      this.observers.push(clsObserver);
    } catch (error) {
      console.error('CLS observation error:', error);
    }
  }

  private observeInteractions() {
    try {
      const fidObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          this.metrics.set('FID', {
            name: 'FID',
            value: (entry as any).processingStart - entry.startTime,
            rating: this.rateMetric('FID', (entry as any).processingStart - entry.startTime),
            delta: (entry as any).processingStart - entry.startTime,
            id: this.generateId(),
          });
        }
      });
      fidObserver.observe({ type: 'first-input', buffered: true });
      this.observers.push(fidObserver);
    } catch (error) {
      console.error('FID observation error:', error);
    }
  }

  private observeResourceTiming() {
    try {
      const resourceObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          const resource = entry as PerformanceResourceTiming;
          if (resource.duration > 1000) {
            console.warn(`[Performance] Slow resource: ${resource.name} (${resource.duration.toFixed(0)}ms)`);
          }
        }
      });
      resourceObserver.observe({ type: 'resource', buffered: true });
      this.observers.push(resourceObserver);
    } catch (error) {
      console.error('Resource timing error:', error);
    }
  }

  private rateMetric(name: string, value: number): 'good' | 'needs-improvement' | 'poor' {
    const thresholds: Record<string, { good: number; poor: number }> = {
      FCP: { good: 1800, poor: 3000 },
      LCP: { good: 2500, poor: 4000 },
      FID: { good: 100, poor: 300 },
      CLS: { good: 0.1, poor: 0.25 },
      INP: { good: 200, poor: 500 },
      TTFB: { good: 800, poor: 1800 },
    };

    const threshold = thresholds[name];
    if (!threshold) return 'good';

    if (value <= threshold.good) return 'good';
    if (value <= threshold.poor) return 'needs-improvement';
    return 'poor';
  }

  private generateId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  getMetrics(): WebVitals {
    const result: WebVitals = {};
    this.metrics.forEach((value, key) => {
      result[key as keyof WebVitals] = value;
    });
    return result;
  }

  getMetric(name: string): PerformanceMetric | undefined {
    return this.metrics.get(name);
  }

  clear() {
    this.metrics.clear();
    this.observers.forEach(observer => observer.disconnect());
    this.observers = [];
  }

  destroy() {
    this.clear();
    PerformanceMonitor.instance = undefined as any;
  }
}

export const performanceMonitor = PerformanceMonitor.getInstance();

/**
 * Route & Component Prefetching Utility
 * Allows preloading pages and dynamic chunks on user interaction (hover/focus)
 * and during browser idle time using requestIdleCallback.
 */

// Cache for loaded modules to avoid duplicate import calls
const prefetchedModules = new Set<string>();

/**
 * Map of page route keys to their dynamic import functions
 */
const routeImportMap: Record<string, () => Promise<unknown>> = {
  home: () => import('@/app/pages/HomePage'),
  about: () => import('@/app/pages/AboutPage'),
  programs: () => import('@/app/pages/ProgramsPage'),
  projects: () => import('@/app/pages/ProjectsPage'),
  success: () => import('@/app/pages/SuccessStoriesPage'),
  news: () => import('@/app/pages/NewsPage'),
  media: () => import('@/app/pages/MediaPage'),
  reports: () => import('@/app/pages/ReportsPage'),
  transparency: () => import('@/app/pages/TransparencyPage'),
  volunteer: () => import('@/app/pages/VolunteerPage'),
  zakat: () => import('@/app/pages/ZakatPage'),
  endowment: () => import('@/app/pages/EndowmentPage'),
  donate: () => import('@/app/pages/DonatePage'),
  contact: () => import('@/app/pages/ContactPage'),
  partners: () => import('@/app/pages/PartnersPage'),
  donor: () => import('@/app/pages/DonorPortalPage'),
  admin: () => import('@/app/pages/AdminPage'),
  search: () => import('@/app/components/SearchOverlay'),
};

/**
 * Prefetches a specific route module on-demand (e.g., hover on nav link)
 */
export function prefetchRoute(pageKey: string): void {
  if (prefetchedModules.has(pageKey)) return;

  const importFn = routeImportMap[pageKey];
  if (importFn) {
    prefetchedModules.add(pageKey);
    importFn().catch(() => {
      // If prefetch fails (e.g., offline), remove from set so it can retry later
      prefetchedModules.delete(pageKey);
    });
  }
}

/**
 * Idle-time preloader that preloads top-priority routes in background
 */
export function initIdlePrefetching(): void {
  if (typeof window === 'undefined') return;

  const priorityPages = ['donate', 'projects', 'programs', 'zakat', 'about'];

  const schedulePrefetch = () => {
    let index = 0;

    const loadNext = (deadline?: IdleDeadline) => {
      while (index < priorityPages.length && (!deadline || deadline.timeRemaining() > 5)) {
        prefetchRoute(priorityPages[index]);
        index++;
      }

      if (index < priorityPages.length) {
        if ('requestIdleCallback' in window) {
          (window as any).requestIdleCallback(loadNext, { timeout: 3000 });
        } else {
          setTimeout(loadNext, 1000);
        }
      }
    };

    if ('requestIdleCallback' in window) {
      (window as any).requestIdleCallback(loadNext, { timeout: 3000 });
    } else {
      setTimeout(loadNext, 2000);
    }
  };

  if (document.readyState === 'complete') {
    schedulePrefetch();
  } else {
    window.addEventListener('load', schedulePrefetch, { once: true });
  }
}

// PWA Utilities - مركز PWA متكامل
import { useEffect, useState } from 'react';

// Register service worker
export async function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {
  if ('serviceWorker' in navigator && import.meta.env.PROD) {
    try {
      const registration = await navigator.serviceWorker.register('/sw.js', {
        scope: '/',
      });
      return registration;
    } catch (error) {
      console.error('SW registration failed:', error);
    }
  }
  return null;
}

// Check if running as PWA
export function isPWA(): boolean {
  return (
    window.matchMedia('(display-mode: standalone)').matches ||
    (navigator as any).standalone === true ||
    document.referrer.includes('android-app://')
  );
}

// Network status hook
export function useNetworkStatus() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return { isOnline };
}

// Connection quality detection
export function getConnectionQuality(): 'excellent' | 'good' | 'slow' | 'offline' {
  if (!navigator.onLine) return 'offline';
  
  const connection = (navigator as any).connection;
  if (!connection) return 'good';

  const { effectiveType, downlink } = connection;
  
  if (effectiveType === '4g' || downlink > 2) return 'excellent';
  if (effectiveType === '3g' || downlink > 0.5) return 'good';
  return 'slow';
}

// Background sync registration
export async function registerBackgroundSync(tag: string, data?: any): Promise<void> {
  if ('serviceWorker' in navigator && 'sync' in (window as any).registration) {
    try {
      const registration = await navigator.serviceWorker.ready;
      await (registration as any).sync.register(tag);
    } catch (error) {
      console.error('Background sync registration failed:', error);
    }
  }
}

// Push notification subscription
export async function subscribeToPush(): Promise<PushSubscription | null> {
  if (!('serviceWorker' in navigator)) return null;

  try {
    const registration = await navigator.serviceWorker.ready;
    const subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
       applicationServerKey: new Uint8Array(urlBase64ToUint8Array(import.meta.env.VITE_PUSH_PUBLIC_KEY || '')),
    });
    return subscription;
  } catch (error) {
    console.error('Push subscription failed:', error);
    return null;
  }
}

// Helper for push key conversion
function urlBase64ToUint8Array(base64String: string): Uint8Array {
  if (!base64String) return new Uint8Array();
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String.replace(/-/g, '+') + padding).replace(/-/g, '+');
  
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

